import { StudentRecord, ScoreSnapshot } from '../types';

/**
 * 获取特定周期、特定科目的名次计算基数（分母）
 * 如果存在导入的名次，则取最大名次值；否则取当前样本总数
 */
export const getEffectiveCohortSize = (
  period: string,
  subject: string | null, // null 表示总分
  periodData: any[],
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>,
  allHistoricalRanks: Record<string, Record<string, number>>
): number => {
  let maxRankFound = 0;

  if (subject) {
    // 处理单科名次基数
    const subRanks = allSubjectRanks[period]?.[subject] || {};
    const values = Object.values(subRanks);
    if (values.length > 0) {
      maxRankFound = Math.max(...values);
    }
  } else {
    // 处理总分名次基数
    const totalRanks = allHistoricalRanks[period] || {};
    const values = Object.values(totalRanks);
    if (values.length > 0) {
      maxRankFound = Math.max(...values);
    }
  }

  // 基数至少是当前文件内的学生数，防止数据异常
  return Math.max(periodData.length, maxRankFound);
};

/**
 * 计算全周期总分名次映射
 */
export const calculateHistoricalRanks = (students: StudentRecord[]) => {
  const allPeriods = Array.from(new Set(students.flatMap(s => s.history.map(h => h.period))));
  const periodRankMap: Record<string, Record<string, number>> = {};

  allPeriods.forEach(period => {
    const hasImportedRanks = students.some(s => {
      const h = s.history.find(p => p.period === period);
      return h?.schoolRank !== undefined && h.schoolRank > 0;
    });

    if (hasImportedRanks) {
      const ranks: Record<string, number> = {};
      students.forEach(s => {
        const h = s.history.find(p => p.period === period);
        if (h && h.schoolRank) ranks[s.name] = h.schoolRank;
      });
      if (Object.keys(ranks).length > 0) {
        periodRankMap[period] = ranks;
        return;
      }
    }

    const periodStudents = students
      .map(s => ({
        name: s.name,
        total: s.history.find(h => h.period === period)?.totalScore ?? -1
      }))
      .filter(s => s.total !== -1)
      .sort((a, b) => b.total - a.total);

    const ranks: Record<string, number> = {};
    periodStudents.forEach((s, idx) => {
      ranks[s.name] = idx + 1;
    });
    periodRankMap[period] = ranks;
  });

  return periodRankMap;
};

/**
 * 计算全周期、全科目的名次映射
 */
export const calculateSubjectHistoricalRanks = (students: StudentRecord[], subjects: string[]) => {
  const allPeriods = Array.from(new Set(students.flatMap(s => s.history.map(h => h.period))));
  const result: Record<string, Record<string, Record<string, number>>> = {};

  allPeriods.forEach(period => {
    result[period] = {};
    subjects.forEach(sub => {
      const hasImportedRanks = students.some(s => {
        const h = s.history.find(p => p.period === period);
        return h?.ranks?.[sub] !== undefined && h.ranks[sub] > 0;
      });

      if (hasImportedRanks) {
        const subRanks: Record<string, number> = {};
        students.forEach(s => {
          const h = s.history.find(p => p.period === period);
          if (h?.ranks?.[sub]) subRanks[s.name] = h.ranks[sub];
        });
        if (Object.keys(subRanks).length > 0) {
          result[period][sub] = subRanks;
          return;
        }
      }

      const subRanks: Record<string, number> = {};
      const sortedStudents = students
        .map(s => ({
          name: s.name,
          score: s.history.find(h => h.period === period)?.scores[sub] ?? -1
        }))
        .filter(s => s.score !== -1)
        .sort((a, b) => b.score - a.score);

      sortedStudents.forEach((s, idx) => {
        subRanks[s.name] = idx + 1;
      });
      result[period][sub] = subRanks;
    });
  });

  return result;
};

/**
 * 根据导入的 Metadata 自动推算名次百分比阈值
 */
export const deriveThresholdsFromMetadata = (
  periodData: any[], 
  labels: { key: string, color: string }[],
  cohortSize: number
): Record<string, number> => {
  const derived: Record<string, number> = {};
  if (cohortSize === 0) return derived;

  let cumulativeCount = 0;
  labels.forEach(label => {
    const count = periodData.filter(s => {
      const status = (s.currentStatus || '').trim();
      return status === label.key || status.includes(label.key);
    }).length;

    cumulativeCount += count;
    // 这里的推算目前还是基于样本内的分布，因为元数据 status 是样本自带的
    // 我们将其存为相对于 cohortSize 的百分比
    derived[label.key] = parseFloat(((cumulativeCount / periodData.length) * 100).toFixed(4));
  });

  return derived;
};

/**
 * 获取特定考试周期的快照数据
 */
export const getPeriodSnapshot = (students: StudentRecord[], selectedPeriod: string, allHistoricalRanks: Record<string, Record<string, number>>) => {
  if (!selectedPeriod) return [];
  const ranks = allHistoricalRanks[selectedPeriod] || {};
  return students.map(s => {
    const historyItem = s.history.find(h => h.period === selectedPeriod);
    return {
      ...s,
      currentTotal: historyItem?.totalScore || 0,
      currentAverage: historyItem?.averageScore || 0,
      currentScores: historyItem?.scores || {},
      currentStatus: historyItem?.status,
      periodSchoolRank: ranks[s.name] || historyItem?.schoolRank || 9999
    };
  }).sort((a, b) => a.periodSchoolRank - b.periodSchoolRank);
};

/**
 * 计算总分上线分布
 */
export const getAdmissionDistribution = (
  period: string,
  periodData: any[],
  thresholds: Record<string, number>,
  thresholdType: 'rank' | 'percent',
  labels: { key: string, color: string }[],
  allHistoricalRanks: Record<string, Record<string, number>>
) => {
  if (!periodData.length) return [];

  const hasImportedStatus = periodData.some(s => s.currentStatus !== undefined && s.currentStatus !== '');

  if (hasImportedStatus) {
    const statusCounts: Record<string, number> = {};
    periodData.forEach(s => {
      const status = (s.currentStatus || '未上线').trim();
      statusCounts[status] = (statusCounts[status] || 0) + 1;
    });

    const results = labels.map(l => ({
      name: l.key,
      value: statusCounts[l.key] || 0,
      color: l.color
    })).filter(r => r.value > 0);

    const otherCount = periodData.length - results.reduce((acc, r) => acc + r.value, 0);
    if (otherCount > 0) {
      results.push({ name: '未上线', value: otherCount, color: '#94a3b8' });
    }
    return results;
  }

  // 关键修正：使用总分名次基数
  const cohortSize = getEffectiveCohortSize(period, null, periodData, {}, allHistoricalRanks);

  const sortedThresholds = [...labels].map(l => ({
    ...l,
    limit: thresholdType === 'rank' 
      ? thresholds[l.key] 
      : Math.round((thresholds[l.key] / 100) * cohortSize)
  })).sort((a, b) => a.limit - b.limit);

  const results = sortedThresholds.map((t, idx) => {
    const prevLimit = idx === 0 ? 0 : sortedThresholds[idx - 1].limit;
    const count = periodData.filter(s => s.periodSchoolRank > prevLimit && s.periodSchoolRank <= t.limit).length;
    return { name: t.key, value: count, color: t.color };
  });

  const lastLimit = sortedThresholds[sortedThresholds.length - 1].limit;
  results.push({
    name: '未上线',
    value: periodData.filter(s => s.periodSchoolRank > lastLimit).length,
    color: '#94a3b8'
  });

  return results.filter(r => r.value > 0);
};

/**
 * 单科上线分布核心逻辑
 */
export const getSubjectDistribution = (
  selectedPeriod: string,
  subject: string,
  selectedClasses: string[],
  periodData: any[],
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>,
  allHistoricalRanks: Record<string, Record<string, number>>,
  thresholds: Record<string, number>,
  thresholdType: 'rank' | 'percent'
) => {
  const filteredData = periodData.filter(s => selectedClasses.includes(s.class));
  const subjectRanks = allSubjectRanks[selectedPeriod]?.[subject] || {};

  // 核心：基于该科目的年级名次最大值来计算基数
  const cohortSize = getEffectiveCohortSize(selectedPeriod, subject, periodData, allSubjectRanks, allHistoricalRanks);

  const labels = [
    { key: '清北', color: '#be123c' },
    { key: 'C9', color: '#1e40af' },
    { key: '高分数', color: '#0369a1' },
    { key: '名校', color: '#0d9488' },
    { key: '特控', color: '#10b981' },
  ];

  const results = labels.map((l, idx) => {
    const limit = thresholdType === 'rank' 
      ? thresholds[l.key] 
      : Math.round((thresholds[l.key] / 100) * cohortSize);

    const prevLimit = idx === 0 ? 0 : (thresholdType === 'rank' 
      ? thresholds[labels[idx-1].key] 
      : Math.round((thresholds[labels[idx-1].key] / 100) * cohortSize));

    const count = filteredData.filter(s => {
      const rank = subjectRanks[s.name];
      return rank !== undefined && rank > prevLimit && rank <= limit;
    }).length;

    return { name: l.key, count, color: l.color };
  });

  const maxLimit = thresholdType === 'rank' 
    ? thresholds[labels[labels.length - 1].key] 
    : Math.round((thresholds[labels[labels.length - 1].key] / 100) * cohortSize);

  results.push({
    name: '未上线',
    count: filteredData.filter(s => {
      const rank = subjectRanks[s.name];
      return rank !== undefined && rank > maxLimit;
    }).length,
    color: '#94a3b8'
  });

  return results.filter(r => r.count > 0);
};

/**
 * 获取特定科目关注名单
 */
export const getBelowLineStudents = (
  selectedPeriod: string,
  subject: string,
  selectedClasses: string[],
  periodData: any[],
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>,
  allHistoricalRanks: Record<string, Record<string, number>>,
  teKongThreshold: number,
  thresholdType: 'rank' | 'percent' = 'rank'
) => {
  const subjectRanks = allSubjectRanks[selectedPeriod]?.[subject] || {};
  const filteredData = periodData.filter(s => selectedClasses.includes(s.class));
  const cohortSize = getEffectiveCohortSize(selectedPeriod, subject, periodData, allSubjectRanks, allHistoricalRanks);

  const effectiveLimit = thresholdType === 'percent' 
    ? Math.round((teKongThreshold / 100) * cohortSize)
    : teKongThreshold;

  return filteredData
    .filter(s => {
      const rank = subjectRanks[s.name];
      return rank !== undefined && rank > effectiveLimit;
    })
    .map(s => ({
      name: s.name,
      class: s.class,
      rank: subjectRanks[s.name]
    }))
    .sort((a, b) => (a.rank as number) - (b.rank as number));
};

/**
 * 获取单科排名等级样式
 */
export const getSubjectRankCategory = (
  rank: number,
  thresholds: Record<string, number>,
  thresholdType: 'rank' | 'percent',
  cohortSize: number
) => {
  const categories = [
    { key: '清北', type: 'king' },
    { key: 'C9', type: 'elite' },
    { key: '高分数', type: 'high' },
    { key: '名校', type: 'standard' },
    { key: '特控', type: 'pass' },
  ];

  for (const cat of categories) {
    const limit = thresholdType === 'rank' 
      ? thresholds[cat.key] 
      : Math.round((thresholds[cat.key] / 100) * cohortSize);

    if (rank <= limit) return cat.type;
  }
  return 'fail';
};

export const calculateProgressCoefficient = (x: number, y: number): number => {
  if (x <= 0 || y <= 0) return 0;
  return parseFloat(((2 * (x - y)) / (x + y)).toFixed(2));
};

export const getProgressAnalysisData = (students: StudentRecord[], periodX: string, periodY: string, allHistoricalRanks: Record<string, Record<string, number>>) => {
  if (!periodX || !periodY) return [];
  const ranksX = allHistoricalRanks[periodX] || {};
  const ranksY = allHistoricalRanks[periodY] || {};

  return students.map(s => {
    const x = ranksX[s.name];
    const y = ranksY[s.name];
    if (x === undefined || y === undefined) return null;
    const coefficient = calculateProgressCoefficient(x, y);
    const streakInfo = calculateStreakInfo(s, allHistoricalRanks);
    return {
      name: s.name,
      class: s.class,
      rankX: x,
      rankY: y,
      rankChange: x - y,
      coefficient,
      streakCount: streakInfo ? (streakInfo.type === 'improvement' ? streakInfo.count : -streakInfo.count) : 0
    };
  }).filter((d): d is NonNullable<typeof d> => d !== null);
};

export const calculateGradeAverages = (students: StudentRecord[]) => {
  const allPeriods = Array.from(new Set(students.flatMap(s => s.history.map(h => h.period))));
  const averages: Record<string, number> = {};
  allPeriods.forEach(period => {
    const totals = students.map(s => s.history.find(h => h.period === period)?.totalScore).filter((t): t is number => t !== undefined);
    if (totals.length > 0) averages[period] = totals.reduce((a, b) => a + b, 0) / totals.length;
  });
  return averages;
};

export const calculateStreakInfo = (student: StudentRecord, allHistoricalRanks: Record<string, Record<string, number>>) => {
  const studentName = student.name;
  const rankList: number[] = student.history.map(h => allHistoricalRanks[h.period]?.[studentName]).filter((r): r is number => r !== undefined);
  if (rankList.length < 2) return null;
  const last = rankList[rankList.length - 1];
  const prev = rankList[rankList.length - 2];
  if (last === prev) return { count: 0, type: 'stable', totalChange: 0, steps: [] };
  const isImproving = last < prev;
  const type = isImproving ? 'improvement' : 'decline';
  let count = 0, totalChange = 0;
  const steps: number[] = [];
  for (let i = rankList.length - 1; i > 0; i--) {
    const current = rankList[i], previous = rankList[i - 1], diff = previous - current;
    if ((isImproving && diff > 0) || (!isImproving && diff < 0)) {
      count++;
      totalChange += diff;
      steps.unshift(diff);
    } else break;
  }
  return { count, type, totalChange, steps };
};

export const getAdmissionCategory = (rank: number, thresholds: Record<string, number>, thresholdType: 'rank' | 'percent', cohortSize: number, snapshotStatus?: string) => {
  if (snapshotStatus && snapshotStatus !== '' && snapshotStatus !== '未上线') return snapshotStatus;
  const lines = [{ key: '清北', label: '清北' }, { key: 'C9', label: 'C9' }, { key: '高分数', label: '高分' }, { key: '名校', label: '名校' }, { key: '特控', label: '特控' }];
  for (const line of lines) {
    const limit = thresholdType === 'rank' ? thresholds[line.key] : Math.round((thresholds[line.key] / 100) * cohortSize);
    if (rank <= limit) return line.label;
  }
  return '未上线';
};

export const calculateExamParameters = (periodData: any[], subjects: string[]) => {
  if (periodData.length === 0) return null;
  const n = periodData.length, stats: any[] = [];
  subjects.forEach(sub => {
    const scores = periodData.map(s => s.currentScores[sub] || 0).sort((a, b) => a - b);
    const sum = scores.reduce((a, b) => a + b, 0), mean = sum / n, max = scores[n - 1];
    let fullScore = max > 120 ? (max > 150 ? Math.ceil(max / 10) * 10 : 150) : (max > 100 ? 120 : 100);
    const variance = scores.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / n;
    const stdDev = Math.sqrt(variance), median = n % 2 === 0 ? (scores[n/2 - 1] + scores[n/2]) / 2 : scores[Math.floor(n/2)];
    const difficulty = mean / fullScore;
    const splitIdx = Math.round(n * 0.27), top27 = scores.slice(n - splitIdx), bottom27 = scores.slice(0, splitIdx);
    const meanTop = top27.length > 0 ? top27.reduce((a, b) => a + b, 0) / top27.length : 0;
    const meanBottom = bottom27.length > 0 ? bottom27.reduce((a, b) => a + b, 0) / bottom27.length : 0;
    const discrimination = (meanTop - meanBottom) / fullScore;
    stats.push({ subject: sub, participants: n, max, mean: parseFloat(mean.toFixed(2)), stdDev: parseFloat(stdDev.toFixed(2)), difficulty: parseFloat(difficulty.toFixed(2)), discrimination: parseFloat(discrimination.toFixed(2)), variance, median });
  });
  const k = subjects.length, sumVarItems = stats.reduce((acc, s) => acc + s.variance, 0);
  const totalScores = periodData.map(s => s.currentTotal), meanTotal = totalScores.reduce((a, b) => a + b, 0) / n;
  const varTotal = totalScores.reduce((a, b) => a + Math.pow(b - meanTotal, 2), 0) / n;
  const reliability = k > 1 ? (k / (k - 1)) * (1 - (sumVarItems / varTotal)) : 1;
  return { subjectStats: stats, reliability: parseFloat(reliability.toFixed(2)) };
};

export const getStudentRadarData = (student: StudentRecord, selectedPeriod: string, subjects: string[], radarBaseline: 'class' | 'grade', periodData: any[]) => {
  const currentScores = student.history.find(h => h.period === selectedPeriod)?.scores || {};
  const baselineSource = radarBaseline === 'class' ? periodData.filter(s => s.class === student.class) : periodData;
  return subjects.map(sub => ({
    subject: sub,
    score: currentScores[sub] || 0,
    baseline: parseFloat((baselineSource.length > 0 ? baselineSource.reduce((acc, s) => acc + (s.currentScores?.[sub] || 0), 0) / baselineSource.length : 0).toFixed(1)),
    fullMark: 150
  }));
};

export const getStudentSubjectTrend = (student: StudentRecord, subject: string, allSubjectRanks: Record<string, Record<string, Record<string, number>>>) => {
  return student.history.map(h => ({ period: h.period, rank: allSubjectRanks[h.period]?.[subject]?.[student.name] || null })).filter(d => d.rank !== null);
};

export const getSubjectAverages = (periodData: any[], subjects: string[]) => {
  return subjects.map(sub => ({ name: sub, avg: parseFloat((periodData.reduce((acc, s) => acc + (s.currentScores[sub] || 0), 0) / periodData.length).toFixed(2)) }));
};

export const getClassSummaries = (periodData: any[], selectedClasses: string[]) => {
  return selectedClasses.map(cls => {
    const clsStudents = periodData.filter(s => s.class === cls);
    const totalAvg = clsStudents.length > 0 ? clsStudents.reduce((acc, s) => acc + s.currentTotal, 0) / clsStudents.length : 0;
    const top10Count = clsStudents.filter(s => s.periodSchoolRank <= 10).length;
    const top50Count = clsStudents.filter(s => s.periodSchoolRank <= 50).length;
    return { className: cls, count: clsStudents.length, average: parseFloat(totalAvg.toFixed(2)), top10: top10Count, top50: top50Count };
  });
};

export const getClassLeaderboard = (classSummaries: any[]) => {
  if (classSummaries.length === 0) return null;
  return {
    highestAvg: [...classSummaries].sort((a, b) => b.average - a.average)[0],
    mostTop10: [...classSummaries].sort((a, b) => b.top10 - a.top10)[0],
    mostTop50: [...classSummaries].sort((a, b) => b.top50 - a.top50)[0],
  };
};

export const calculateHeatmapMaxValues = (data: any[], selectedClasses: string[]) => {
  const map: Record<string, number> = {};
  data.forEach(row => { map[row.name] = Math.max(...selectedClasses.map(cls => row[cls] || 0)); });
  return map;
};

import React, { useState, useMemo } from 'react';
import { Users, Layers, Target, Award, History, Crown, Calculator, Calendar, BarChart3, TrendingUp } from 'lucide-react';
import { AnalysisState } from '../types';
import { StatCard, TabButton } from './SharedComponents';
import * as AnalysisEngine from '../utils/analysisUtils';

// View Imports
import SchoolView from './SchoolView';
import ClassComparisonView from './ClassComparisonView';
import EliteBenchmarksView from './EliteBenchmarksView';
import ExamParametersView from './ExamParametersView';
import StudentDetailView from './StudentDetailView';
import SubjectAnalysisView from './SubjectAnalysisView';
import ProgressAnalysisView from './ProgressAnalysisView';

const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316'];

const Dashboard: React.FC<{ data: AnalysisState }> = ({ data }) => {
  const [activeTab, setActiveTab] = useState<'school' | 'comparison' | 'kings' | 'subjectAnalysis' | 'parameters' | 'student' | 'progress'>('school');

  const allPeriods = useMemo(() => 
    data.students[0]?.history.map(h => h.period) || [], 
    [data.students]
  );

  const [selectedPeriod, setSelectedPeriod] = useState<string>(allPeriods[allPeriods.length - 1] || '');
  const [selectedClasses, setSelectedClasses] = useState<string[]>([data.classes[0]]);
  const [benchmarkClass, setBenchmarkClass] = useState(data.classes[0]);
  const [selectedStudentId, setSelectedStudentId] = useState(data.students[0]?.id);

  const [studentSearchTerm, setStudentSearchTerm] = useState('');
  const [classFilter, setClassFilter] = useState<string>('all');

  const [thresholdType, setThresholdType] = useState<'rank' | 'percent'>('rank');
  const [manualThresholds, setManualThresholds] = useState<Record<string, number>>({
    '清北': 5, 'C9': 30, '高分数': 100, '名校': 300, '特控': 600,
  });

  const admissionLabels = [
    { key: '清北', color: '#be123c' },
    { key: 'C9', color: '#1e40af' },
    { key: '高分数', color: '#0369a1' },
    { key: '名校', color: '#0d9488' },
    { key: '特控', color: '#10b981' },
  ];

  const allHistoricalRanks = useMemo(() => 
    AnalysisEngine.calculateHistoricalRanks(data.students), 
    [data.students]
  );

  const allSubjectRanks = useMemo(() => 
    AnalysisEngine.calculateSubjectHistoricalRanks(data.students, data.subjects),
    [data.students, data.subjects]
  );

  const gradeAveragesByPeriod = useMemo(() => 
    AnalysisEngine.calculateGradeAverages(data.students), 
    [data.students]
  );

  const periodData = useMemo(() => 
    AnalysisEngine.getPeriodSnapshot(data.students, selectedPeriod, allHistoricalRanks),
    [data.students, selectedPeriod, allHistoricalRanks]
  );

  const hasImportedStatus = useMemo(() => 
    periodData.some(s => s.currentStatus !== undefined && s.currentStatus !== ''),
    [periodData]
  );

  // 获取总分基数用于阈值推算
  const totalCohortSize = useMemo(() => 
    AnalysisEngine.getEffectiveCohortSize(selectedPeriod, null, periodData, {}, allHistoricalRanks),
    [selectedPeriod, periodData, allHistoricalRanks]
  );

  const thresholds = useMemo(() => {
    if (hasImportedStatus) {
      return AnalysisEngine.deriveThresholdsFromMetadata(periodData, admissionLabels, totalCohortSize);
    }
    return manualThresholds;
  }, [hasImportedStatus, periodData, totalCohortSize, manualThresholds]);

  const effectiveThresholdType = hasImportedStatus ? 'percent' : thresholdType;

  const examParameters = useMemo(() => 
    AnalysisEngine.calculateExamParameters(periodData, data.subjects),
    [periodData, data.subjects]
  );

  const aboveLineCount = useMemo(() => {
    if (hasImportedStatus) {
      const validLabels = ['清北', 'C9', '高分', '名校', '特控', '上线', '一本', '本科'];
      return periodData.filter(s => {
        const status = s.currentStatus || '';
        return status !== '' && status !== '未上线' && validLabels.some(label => status.includes(label));
      }).length;
    }

    const limit = effectiveThresholdType === 'rank' 
      ? (thresholds['特控'] || 0) 
      : Math.round(((thresholds['特控'] || 0) / 100) * totalCohortSize);
    return periodData.filter(s => s.periodSchoolRank <= limit).length;
  }, [periodData, thresholds, effectiveThresholdType, hasImportedStatus, totalCohortSize]);

  return (
    <div className="space-y-8 animate-in fade-in duration-700 pb-12">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatCard icon={<Users className="w-5 h-5 text-blue-600" />} title="Students in File" value={data.students.length.toString()} subtitle="Current Sample" />
        <StatCard icon={<Layers className="w-5 h-5 text-green-600" />} title="Classes" value={data.classes.length.toString()} subtitle="Active Groups" />
        <StatCard icon={<Target className="w-5 h-5 text-purple-600" />} title="上线人数" value={aboveLineCount.toString()} subtitle={`Based on ${selectedPeriod}`} />
        <StatCard icon={<Award className="w-5 h-5 text-orange-600" />} title="Grade Size (Est)" value={totalCohortSize.toString()} subtitle="Computed Cohort Size" />
      </div>

      <div className="flex flex-col lg:flex-row gap-4 items-start lg:items-center justify-between">
        <div className="flex flex-wrap gap-1 bg-white p-1.5 rounded-2xl shadow-sm border border-gray-100 w-fit">
          <TabButton active={activeTab === 'school'} onClick={() => setActiveTab('school')} icon={<History className="w-4 h-4"/>} label="School View" />
          <TabButton active={activeTab === 'comparison'} onClick={() => setActiveTab('comparison')} icon={<Layers className="w-4 h-4"/>} label="Class Comparison" />
          <TabButton active={activeTab === 'kings'} onClick={() => setActiveTab('kings')} icon={<Crown className="w-4 h-4"/>} label="Elite Benchmarks" />
          <TabButton active={activeTab === 'parameters'} onClick={() => setActiveTab('parameters')} icon={<Calculator className="w-4 h-4"/>} label="Exam Parameters" />
          <TabButton active={activeTab === 'subjectAnalysis'} onClick={() => setActiveTab('subjectAnalysis')} icon={<BarChart3 className="w-4 h-4"/>} label="Subject Analysis" />
          <TabButton active={activeTab === 'progress'} onClick={() => setActiveTab('progress')} icon={<TrendingUp className="w-4 h-4"/>} label="Progress Analysis" />
          <TabButton active={activeTab === 'student'} onClick={() => setActiveTab('student')} icon={<Target className="w-4 h-4"/>} label="Student Detail" />
        </div>
        <div className="flex items-center gap-3 bg-blue-50/50 px-4 py-2 rounded-2xl border border-blue-100 animate-in slide-in-from-right-4">
          <Calendar className="w-4 h-4 text-blue-600" />
          <select className="bg-transparent border-none text-sm font-black text-blue-900 focus:ring-0 cursor-pointer" value={selectedPeriod} onChange={(e) => setSelectedPeriod(e.target.value)}>
            {allPeriods.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
        </div>
      </div>

      <div className="w-full">
        {activeTab === 'school' && (
          <SchoolView 
            selectedPeriod={selectedPeriod} 
            periodData={periodData} 
            subjects={data.subjects} 
            thresholds={thresholds} 
            setThresholds={setManualThresholds} 
            thresholdType={effectiveThresholdType} 
            setThresholdType={setThresholdType} 
            hasImportedStatus={hasImportedStatus} 
            totalStudents={totalCohortSize}
            allHistoricalRanks={allHistoricalRanks}
          />
        )}
        {activeTab === 'comparison' && <ClassComparisonView selectedPeriod={selectedPeriod} classes={data.classes} selectedClasses={selectedClasses} setSelectedClasses={setSelectedClasses} classComparisonData={classComparisonData} rankingDistributionData={rankingDistributionData} colors={colors} periodData={periodData} />}
        {activeTab === 'kings' && <EliteBenchmarksView selectedPeriod={selectedPeriod} classes={data.classes} benchmarkClass={benchmarkClass} setBenchmarkClass={setBenchmarkClass} kingsData={kingsData} duelData={duelData} />}
        {activeTab === 'parameters' && <ExamParametersView selectedPeriod={selectedPeriod} examParameters={examParameters} colors={colors} totalParticipants={periodData.length} />}
        {activeTab === 'subjectAnalysis' && (
          <SubjectAnalysisView 
            selectedPeriod={selectedPeriod}
            periodData={periodData}
            subjects={data.subjects}
            classes={data.classes}
            allSubjectRanks={allSubjectRanks}
            allHistoricalRanks={allHistoricalRanks}
            thresholds={thresholds}
            thresholdType={effectiveThresholdType}
          />
        )}
        {activeTab === 'progress' && <ProgressAnalysisView students={data.students} allPeriods={allPeriods} allHistoricalRanks={allHistoricalRanks} classes={data.classes} />}
        {activeTab === 'student' && (
          <StudentDetailView 
            studentSearchTerm={studentSearchTerm} setStudentSearchTerm={setStudentSearchTerm} 
            classFilter={classFilter} setClassFilter={setClassFilter} classes={data.classes} 
            selectableStudents={data.students.filter(s => s.name.toLowerCase().includes(studentSearchTerm.toLowerCase()) && (classFilter === 'all' || s.class === classFilter))} 
            selectedStudentId={selectedStudentId} setSelectedStudentId={setSelectedStudentId} 
            selectedStudent={data.students.find(s => s.id === selectedStudentId)} 
            subjects={data.subjects} gradeAveragesByPeriod={gradeAveragesByPeriod} 
            allHistoricalRanks={allHistoricalRanks}
            allSubjectRanks={allSubjectRanks}
            thresholds={thresholds}
            thresholdType={effectiveThresholdType}
            totalStudents={totalCohortSize}
            selectedPeriod={selectedPeriod}
            periodData={periodData}
          />
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useMemo } from 'react';
import { ResponsiveContainer, PieChart, Pie, Cell, Tooltip, Legend, BarChart, Bar, XAxis, YAxis, CartesianGrid } from 'recharts';
import { Settings2, ChevronDown, ChevronUp, ShieldCheck } from 'lucide-react';
import { ChartContainer } from './SharedComponents';
import * as AnalysisEngine from '../utils/analysisUtils';

interface SchoolViewProps {
  selectedPeriod: string;
  periodData: any[];
  subjects: string[];
  thresholds: Record<string, number>;
  setThresholds: React.Dispatch<React.SetStateAction<Record<string, number>>>;
  thresholdType: 'rank' | 'percent';
  setThresholdType: React.Dispatch<React.SetStateAction<'rank' | 'percent'>>;
  hasImportedStatus?: boolean;
  totalStudents: number;
  allHistoricalRanks: Record<string, Record<string, number>>;
}

const SchoolView: React.FC<SchoolViewProps> = ({ 
  selectedPeriod, 
  periodData, 
  subjects,
  thresholds,
  setThresholds,
  thresholdType,
  setThresholdType,
  hasImportedStatus = false,
  totalStudents,
  allHistoricalRanks
}) => {
  const [showSettings, setShowSettings] = useState(false);

  const admissionLabels = [
    { key: '清北', color: '#be123c' },
    { key: 'C9', color: '#1e40af' },
    { key: '高分数', color: '#0369a1' },
    { key: '名校', color: '#0d9488' },
    { key: '特控', color: '#10b981' },
  ];

  const handleThresholdChange = (key: string, val: string) => {
    const num = parseFloat(val) || 0;
    setThresholds(prev => ({ ...prev, [key]: num }));
  };

  const admissionDistribution = useMemo(() => 
    AnalysisEngine.getAdmissionDistribution(selectedPeriod, periodData, thresholds, thresholdType, admissionLabels, allHistoricalRanks),
    [selectedPeriod, periodData, thresholds, thresholdType, allHistoricalRanks]
  );

  const subjectAvgs = useMemo(() => 
    AnalysisEngine.getSubjectAverages(periodData, subjects),
    [periodData, subjects]
  );

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
      <section className="bg-white rounded-2xl border border-gray-100 shadow-sm overflow-hidden">
        <button 
          onClick={() => setShowSettings(!showSettings)}
          className="w-full px-6 py-4 flex items-center justify-between text-sm font-bold text-gray-600 hover:bg-gray-50 transition-colors"
        >
          <div className="flex items-center gap-2">
            <Settings2 className="w-4 h-4 text-blue-600" />
            上线分析参数配置 (Admissions Thresholds)
          </div>
          <div className="flex items-center gap-4">
            {hasImportedStatus && (
              <span className="flex items-center gap-1.5 px-3 py-1 bg-indigo-50 text-indigo-600 rounded-lg text-[10px] font-black uppercase tracking-widest">
                <ShieldCheck className="w-3 h-3" /> 使用导入元数据推算
              </span>
            )}
            {showSettings ? <ChevronUp className="w-4 h-4" /> : <ChevronDown className="w-4 h-4" />}
          </div>
        </button>

        {showSettings && (
          <div className="px-6 pb-6 pt-2 space-y-6 animate-in slide-in-from-top-2">
            {!hasImportedStatus ? (
              <>
                <div className="flex items-center gap-4 bg-gray-50 p-2 rounded-xl w-fit">
                  <button 
                    onClick={() => setThresholdType('rank')}
                    className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${thresholdType === 'rank' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400'}`}
                  >
                    按绝对名次 (Rank)
                  </button>
                  <button 
                    onClick={() => setThresholdType('percent')}
                    className={`px-4 py-1.5 rounded-lg text-xs font-bold transition-all ${thresholdType === 'percent' ? 'bg-white shadow-sm text-blue-600' : 'text-gray-400'}`}
                  >
                    按百分比 (%)
                  </button>
                </div>

                <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
                  {admissionLabels.map(line => (
                    <div key={line.key} className="space-y-2">
                      <label className="text-[10px] font-black text-gray-400 uppercase tracking-widest flex items-center gap-1.5">
                        <div className="w-2 h-2 rounded-full" style={{ backgroundColor: line.color }} />
                        {line.key}
                      </label>
                      <div className="relative">
                        <input 
                          type="number"
                          step={thresholdType === 'percent' ? "0.01" : "1"}
                          value={thresholds[line.key]}
                          onChange={(e) => handleThresholdChange(line.key, e.target.value)}
                          className="w-full px-3 py-2 bg-gray-50 border border-gray-200 rounded-lg text-sm font-bold focus:ring-2 focus:ring-blue-500 outline-none transition-all"
                        />
                        <span className="absolute right-3 top-1/2 -translate-y-1/2 text-[10px] text-gray-400 font-bold">
                          {thresholdType === 'rank' ? '位' : '%'}
                        </span>
                      </div>
                    </div>
                  ))}
                </div>
              </>
            ) : (
              <div className="bg-blue-50/50 p-6 rounded-2xl border border-blue-100 flex flex-col items-center text-center">
                <ShieldCheck className="w-10 h-10 text-blue-600 mb-3" />
                <h4 className="text-sm font-bold text-blue-900 mb-2">已开启“导入元数据”优先模式</h4>
                <p className="text-xs text-blue-800 max-w-lg leading-relaxed">
                  系统推算出各级别的“百分比阈值”如下。注意：此百分比在应用到各个学科时，会自动乘以该学科年级真实出现的最高名次作为分母。
                </p>
                <div className="grid grid-cols-2 sm:grid-cols-5 gap-3 mt-4 w-full">
                  {admissionLabels.map(label => {
                    const pct = thresholds[label.key] || 0;
                    const approxRank = Math.round((pct / 100) * totalStudents);
                    return (
                      <div key={label.key} className="bg-white p-3 rounded-xl border border-blue-200 shadow-sm">
                        <p className="text-[10px] font-black text-gray-400 uppercase mb-1">{label.key}</p>
                        <p className="text-lg font-black text-blue-600">{pct.toFixed(2)}%</p>
                        <p className="text-[10px] text-gray-400 font-medium">基数 {totalStudents} 对应 #{approxRank}</p>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        )}
      </section>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
        <ChartContainer title={`Admissions Distribution (${selectedPeriod})`}>
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Pie data={admissionDistribution} cx="50%" cy="50%" innerRadius={60} outerRadius={85} paddingAngle={5} dataKey="value">
                {admissionDistribution.map((entry: any, index: number) => <Cell key={`cell-${index}`} fill={entry.color} stroke="none" />)}
              </Pie>
              <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} formatter={(value: number) => [`${value} 人`, '数量']} />
              <Legend verticalAlign="bottom" wrapperStyle={{ paddingTop: '20px' }} />
            </PieChart>
          </ResponsiveContainer>
        </ChartContainer>

        <ChartContainer title={`Subject Performance (${selectedPeriod})`}>
          <ResponsiveContainer width="100%" height="100%">
            <BarChart data={subjectAvgs}>
              <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
              <XAxis dataKey="name" stroke="#94a3b8" fontSize={12} />
              <YAxis stroke="#94a3b8" fontSize={12} />
              <Tooltip cursor={{ fill: '#f8fafc' }} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} />
              <Bar dataKey="avg" fill="#3b82f6" radius={[6, 6, 0, 0]} name="Average Score" />
            </BarChart>
          </ResponsiveContainer>
        </ChartContainer>
      </div>
    </div>
  );
};

export default SchoolView;

import React, { useState, useMemo } from 'react';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, LabelList } from 'recharts';
import { Filter, Search, UserX, Info } from 'lucide-react';
import { ChartContainer } from './SharedComponents';
import * as AnalysisEngine from '../utils/analysisUtils';

interface SubjectAnalysisViewProps {
  selectedPeriod: string;
  periodData: any[];
  subjects: string[];
  classes: string[];
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>;
  allHistoricalRanks: Record<string, Record<string, number>>;
  thresholds: Record<string, number>;
  thresholdType: 'rank' | 'percent';
}

const SubjectAnalysisView: React.FC<SubjectAnalysisViewProps> = ({
  selectedPeriod, periodData, subjects, classes, allSubjectRanks, allHistoricalRanks, thresholds, thresholdType
}) => {
  const [selectedSubject, setSelectedSubject] = useState(subjects[0] || '');
  const [selectedClasses, setSelectedClasses] = useState<string[]>([classes[0]]);

  const teKongThresholdValue = useMemo(() => thresholds['特控'] || 0, [thresholds]);

  const distributionData = useMemo(() => 
    AnalysisEngine.getSubjectDistribution(
      selectedPeriod, selectedSubject, selectedClasses, periodData, allSubjectRanks, allHistoricalRanks, thresholds, thresholdType
    ),
    [selectedPeriod, selectedSubject, selectedClasses, periodData, allSubjectRanks, allHistoricalRanks, thresholds, thresholdType]
  );

  const belowLineStudents = useMemo(() => 
    AnalysisEngine.getBelowLineStudents(
      selectedPeriod, selectedSubject, selectedClasses, periodData, allSubjectRanks, allHistoricalRanks, teKongThresholdValue, thresholdType
    ),
    [selectedPeriod, selectedSubject, selectedClasses, periodData, allSubjectRanks, allHistoricalRanks, teKongThresholdValue, thresholdType]
  );

  const cohortSize = useMemo(() => 
    AnalysisEngine.getEffectiveCohortSize(selectedPeriod, selectedSubject, periodData, allSubjectRanks, allHistoricalRanks),
    [selectedPeriod, selectedSubject, periodData, allSubjectRanks, allHistoricalRanks]
  );

  const toggleClass = (cls: string) => {
    setSelectedClasses(prev => prev.includes(cls) ? prev.filter(p => p !== cls) : [...prev, cls]);
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
      <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm flex flex-col md:flex-row gap-6">
        <div className="space-y-3 flex-1">
          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2"><Search className="w-3 h-3" /> Select Subject</p>
          <div className="flex flex-wrap gap-2">
            {subjects.map(sub => (
              <button key={sub} onClick={() => setSelectedSubject(sub)} className={`px-4 py-2 rounded-xl text-sm font-semibold transition-all border ${selectedSubject === sub ? 'bg-indigo-600 text-white border-indigo-600 shadow-md' : 'bg-gray-50 text-gray-500 border-gray-200 hover:border-indigo-300'}`}>{sub}</button>
            ))}
          </div>
        </div>
        <div className="space-y-3 flex-1">
          <p className="text-[10px] font-bold text-gray-400 uppercase tracking-widest flex items-center gap-2"><Filter className="w-3 h-3" /> Select Classes</p>
          <div className="flex flex-wrap gap-2">
            {classes.map(cls => (
              <button key={cls} onClick={() => toggleClass(cls)} className={`px-4 py-2 rounded-xl text-sm font-semibold transition-all border ${selectedClasses.includes(cls) ? 'bg-blue-600 text-white border-blue-600 shadow-md' : 'bg-gray-50 text-gray-500 border-gray-200 hover:border-blue-300'}`}>{cls}</button>
            ))}
          </div>
        </div>
      </div>

      <ChartContainer title={`${selectedSubject} Distribution (${selectedPeriod}) - 基数: ${cohortSize}`}>
        <ResponsiveContainer width="100%" height="100%">
          <BarChart data={distributionData} margin={{ top: 20, right: 30, left: 20, bottom: 20 }}>
            <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
            <XAxis dataKey="name" stroke="#94a3b8" fontSize={12} />
            <YAxis stroke="#94a3b8" fontSize={12} />
            <Tooltip cursor={{ fill: '#f8fafc' }} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} formatter={(value: number) => [`${value} 人`, '人数']} />
            <Bar dataKey="count" radius={[6, 6, 0, 0]} barSize={50}>
              {distributionData.map((entry, index) => <Cell key={`cell-${index}`} fill={entry.color} />)}
              <LabelList dataKey="count" position="top" style={{ fill: '#64748b', fontSize: '12px', fontWeight: 'bold' }} />
            </Bar>
          </BarChart>
        </ResponsiveContainer>
      </ChartContainer>

      <div className="bg-white rounded-3xl border border-rose-100 shadow-sm overflow-hidden animate-in fade-in slide-in-from-bottom-4 duration-500">
        <div className="px-8 py-6 bg-rose-50/50 border-b border-rose-100 flex items-center justify-between">
          <div>
            <h3 className="text-xs font-bold text-rose-600 uppercase tracking-widest flex items-center gap-2"><UserX className="w-4 h-4" /> Focus List</h3>
            <p className="text-[10px] text-rose-400 mt-1">当前选择范围内，{selectedSubject} 未达上线标准的学生</p>
          </div>
        </div>
        <div className="p-8">
          {belowLineStudents.length > 0 ? (
            <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3">
              {belowLineStudents.map((s, idx) => (
                <div key={idx} className="bg-white border border-rose-100 rounded-xl p-3 flex flex-col gap-1 hover:shadow-md transition-all hover:scale-[1.02]">
                  <span className="text-sm font-bold text-gray-800">{s.name}</span>
                  <div className="flex items-center justify-between text-[10px]"><span className="text-gray-400">{s.class}</span><span className="text-rose-600 font-black">#{s.rank}</span></div>
                </div>
              ))}
            </div>
          ) : (
            <div className="flex flex-col items-center justify-center py-10 text-gray-400 italic">
              <Info className="w-8 h-8 mb-2 opacity-20 text-green-500" /><p className="text-sm">Great! No students in the selected group are below the thresholds.</p>
            </div>
          )}
        </div>
      </div>

      <div className="bg-blue-50/50 p-6 rounded-2xl border border-blue-100">
        <h4 className="text-xs font-bold text-blue-900 uppercase tracking-widest mb-3">Analysis Insight</h4>
        <p className="text-sm text-blue-800 leading-relaxed">
          上线阈值计算基于该科目年级最高出现的名次（<strong>基数: {cohortSize}</strong>）。这意味着即使你只导入了一个班的数据，只要排名列显示过 800，名次线也会基于 800 人计算，从而确保分析的真实性。
        </p>
      </div>
    </div>
  );
};

export default SubjectAnalysisView;

import React, { useState, useMemo, useCallback } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer, RadarChart, PolarGrid, PolarAngleAxis, PolarRadiusAxis, Radar } from 'recharts';
import { Search, Filter, GraduationCap, TrendingUp, TrendingDown, Table as TableIcon, Flame } from 'lucide-react';
import { StudentRecord } from '../types';
import { ChartContainer } from './SharedComponents';
import * as AnalysisEngine from '../utils/analysisUtils';

interface StudentDetailViewProps {
  studentSearchTerm: string;
  setStudentSearchTerm: (s: string) => void;
  classFilter: string;
  setClassFilter: (c: string) => void;
  classes: string[];
  selectableStudents: StudentRecord[];
  selectedStudentId: string | undefined;
  setSelectedStudentId: (id: string) => void;
  selectedStudent: StudentRecord | undefined;
  subjects: string[];
  gradeAveragesByPeriod: Record<string, number>;
  allHistoricalRanks: Record<string, Record<string, number>>;
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>;
  thresholds: Record<string, number>;
  thresholdType: 'rank' | 'percent';
  totalStudents: number;
  selectedPeriod: string;
  periodData: any[];
}

const StudentDetailView: React.FC<StudentDetailViewProps> = ({ 
  studentSearchTerm, setStudentSearchTerm, classFilter, setClassFilter, classes, selectableStudents, selectedStudentId, setSelectedStudentId, selectedStudent, subjects, gradeAveragesByPeriod, allHistoricalRanks, allSubjectRanks, thresholds, thresholdType, totalStudents, selectedPeriod, periodData
}) => {
  const [radarBaseline, setRadarBaseline] = useState<'class' | 'grade'>('class');
  const [selectedSubjectForTrend, setSelectedSubjectForTrend] = useState<string>(subjects[0] || '');

  const chartData = useMemo(() => {
    if (!selectedStudent) return [];
    return selectedStudent.history.map(h => ({
      ...h,
      gradeAvgTotal: gradeAveragesByPeriod[h.period] || 0,
      schoolRank: allHistoricalRanks[h.period]?.[selectedStudent.name] || null
    }));
  }, [selectedStudent, gradeAveragesByPeriod, allHistoricalRanks]);

  const historyMeanTotal = useMemo(() => {
    if (!selectedStudent || selectedStudent.history.length === 0) return 0;
    return selectedStudent.history.reduce((acc, h) => acc + h.totalScore, 0) / selectedStudent.history.length;
  }, [selectedStudent]);

  const streakInfo = useMemo(() => 
    selectedStudent ? AnalysisEngine.calculateStreakInfo(selectedStudent, allHistoricalRanks) : null,
    [selectedStudent, allHistoricalRanks]
  );

  const radarData = useMemo(() => {
    if (!selectedStudent || !selectedPeriod) return [];
    return AnalysisEngine.getStudentRadarData(selectedStudent, selectedPeriod, subjects, radarBaseline, periodData);
  }, [selectedStudent, selectedPeriod, subjects, radarBaseline, periodData]);

  const subjectTrendData = useMemo(() => {
    if (!selectedStudent || !selectedSubjectForTrend) return [];
    return AnalysisEngine.getStudentSubjectTrend(selectedStudent, selectedSubjectForTrend, allSubjectRanks);
  }, [selectedStudent, selectedSubjectForTrend, allSubjectRanks]);

  const getStatusLabel = useCallback((period: string, studentName: string) => {
    const rank = allHistoricalRanks[period]?.[studentName];
    if (!rank) return '-';
    // 注意：这里的 totalStudents 此时已经是总分的名次基数
    const snapshot = selectedStudent?.history.find(h => h.period === period);
    return AnalysisEngine.getAdmissionCategory(rank, thresholds, thresholdType, totalStudents, snapshot?.status);
  }, [allHistoricalRanks, thresholds, thresholdType, totalStudents, selectedStudent]);

  const getSubjectCellStyle = useCallback((period: string, subject: string, studentName: string) => {
    const subRanksForPeriod = allSubjectRanks[period]?.[subject] || {};
    const rank = subRanksForPeriod[studentName];
    if (!rank) return 'text-gray-400';

    // 核心修正：单科分析使用单科名次基数
    const cohortSize = AnalysisEngine.getEffectiveCohortSize(period, subject, periodData, allSubjectRanks, allHistoricalRanks);
    const category = AnalysisEngine.getSubjectRankCategory(rank, thresholds, thresholdType, cohortSize);

    const styles: Record<string, string> = {
      'king': 'bg-purple-100 text-purple-900 border-purple-200 font-bold border-b-2',
      'elite': 'bg-green-100 text-green-900 border-green-200 font-bold border-b-2',
      'high': 'bg-blue-100 text-blue-900 border-blue-200 font-bold border-b-2',
      'standard': 'text-gray-600',
      'pass': 'bg-yellow-100 text-yellow-900 border-yellow-200 font-bold border-b-2',
      'fail': 'bg-red-50 text-red-700 border-red-100 font-bold border-b-2'
    };
    return styles[category] || styles['standard'];
  }, [allSubjectRanks, thresholds, thresholdType, periodData, allHistoricalRanks]);

  return (
    <div className="space-y-8 animate-in slide-in-from-right-4 duration-300">
      <div className="bg-white p-6 rounded-2xl border border-gray-100 shadow-sm space-y-4">
        <div className="flex flex-col md:flex-row gap-4">
          <div className="relative flex-1">
            <Search className="w-4 h-4 text-gray-400 absolute left-3 top-1/2 -translate-y-1/2" />
            <input type="text" placeholder="Search..." value={studentSearchTerm} onChange={(e) => setStudentSearchTerm(e.target.value)} className="w-full pl-10 pr-4 py-3 bg-gray-50 border border-gray-200 rounded-xl text-sm outline-none focus:ring-2 focus:ring-blue-500 transition-all" />
          </div>
          <select className="bg-gray-50 border border-gray-200 rounded-xl px-4 py-3 text-sm outline-none focus:ring-2 focus:ring-blue-500" value={classFilter} onChange={(e) => setClassFilter(e.target.value)}>
            <option value="all">All Classes</option>
            {classes.map(c => <option key={c} value={c}>{c}</option>)}
          </select>
        </div>
        <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 lg:grid-cols-6 gap-3 max-h-[200px] overflow-y-auto p-1 custom-scrollbar">
          {selectableStudents.map(s => (
            <button key={s.id} onClick={() => setSelectedStudentId(s.id)} className={`text-left p-3 rounded-xl border transition-all text-xs flex flex-col gap-1 ${selectedStudentId === s.id ? 'bg-blue-600 border-blue-600 text-white shadow-md' : 'bg-white border-gray-100 hover:border-blue-300 text-gray-700'}`}>
              <span className="font-bold truncate">{s.name}</span>
              <span className={`text-[10px] opacity-70 ${selectedStudentId === s.id ? 'text-blue-100' : 'text-gray-400'}`}>{s.class}</span>
            </button>
          ))}
        </div>
      </div>

      {selectedStudent ? (
        <>
          <div className="grid grid-cols-1 lg:grid-cols-3 gap-8">
            <div className="lg:col-span-1 space-y-6">
              <div className="bg-gradient-to-br from-indigo-600 to-blue-700 p-8 rounded-2xl shadow-xl text-white">
                <div className="flex justify-between items-start mb-6">
                  <div className="w-14 h-14 bg-white/20 rounded-2xl flex items-center justify-center backdrop-blur-md border border-white/20"><GraduationCap className="w-8 h-8 text-white" /></div>
                  <div className="text-right">
                    <p className="text-[10px] opacity-70 uppercase font-black tracking-widest">Latest Rank</p>
                    <p className="text-4xl font-black">#{allHistoricalRanks[selectedStudent.history[selectedStudent.history.length-1].period]?.[selectedStudent.name] || 'N/A'}</p>
                  </div>
                </div>
                <h4 className="text-2xl font-black mb-1">{selectedStudent.name}</h4>
                <p className="text-sm opacity-80 mb-6">{selectedStudent.class}</p>
              </div>

              {streakInfo && streakInfo.count > 0 && (
                <div className={`p-6 rounded-2xl border shadow-sm transition-all animate-in slide-in-from-left-4 ${streakInfo.type === 'improvement' ? 'bg-emerald-50 border-emerald-100' : 'bg-rose-50 border-rose-100'}`}>
                   <div className="flex items-center gap-3 mb-4">
                    <div className={`p-2 rounded-xl ${streakInfo.type === 'improvement' ? 'bg-emerald-500' : 'bg-rose-500'}`}><Flame className="w-5 h-5 text-white" /></div>
                    <div><p className={`text-[10px] font-black uppercase tracking-widest ${streakInfo.type === 'improvement' ? 'text-emerald-600' : 'text-rose-600'}`}>Trend</p><h4 className={`text-lg font-black ${streakInfo.type === 'improvement' ? 'text-emerald-900' : 'text-rose-900'}`}>连续{streakInfo.type === 'improvement' ? '进步' : '退步'} {streakInfo.count} 次</h4></div>
                  </div>
                </div>
              )}
            </div>

            <div className="lg:col-span-2 space-y-8">
              <ChartContainer title="📉 School Ranking Trend">
                <ResponsiveContainer width="100%" height="100%">
                  <LineChart data={chartData}>
                    <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" /><XAxis dataKey="period" stroke="#94a3b8" fontSize={12} /><YAxis reversed domain={['auto', 'auto']} stroke="#94a3b8" fontSize={12} />
                    <Tooltip contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgba(0,0,0,0.1)' }} formatter={(value: number) => [`第 ${value} 名`, 'Rank']} />
                    <Line type="monotone" dataKey="schoolRank" name="Rank" stroke="#8b5cf6" strokeWidth={4} dot={{r: 6, fill: '#8b5cf6', strokeWidth: 2, stroke: '#fff'}} />
                  </LineChart>
                </ResponsiveContainer>
              </ChartContainer>
            </div>
          </div>

          <div className="bg-white rounded-3xl border border-gray-100 shadow-sm overflow-hidden">
            <div className="px-8 py-6 bg-gray-50/50 border-b border-gray-100 flex items-center justify-between">
              <div>
                <h3 className="text-xs font-bold text-gray-500 uppercase tracking-widest flex items-center gap-2"><TableIcon className="w-4 h-4" /> Historical Grade Ledger</h3>
                <p className="text-[10px] text-gray-400 mt-1 italic">Note: 学科颜色基于该科目的年级名次最大值动态适配。</p>
              </div>
            </div>
            <div className="overflow-x-auto">
              <table className="w-full text-left text-sm">
                <thead>
                  <tr className="bg-white text-gray-400 font-bold border-b border-gray-100">
                    <th className="px-8 py-5">Period</th>
                    {subjects.flatMap(s => [
                      <th key={s} className="px-8 py-5 text-center">{s}</th>,
                      <th key={`${s}-rank`} className="px-4 py-5 text-center text-gray-400 font-medium">{s.substring(0, 1)}名</th>
                    ])}
                    <th className="px-8 py-5 text-indigo-600 text-right">My Total</th>
                    <th className="px-8 py-5 text-center text-blue-600">上线</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {selectedStudent.history.map((h, i) => (
                    <tr key={i} className="hover:bg-blue-50/40 transition-colors">
                      <td className="px-8 py-5 font-bold text-gray-700">{h.period}</td>
                      {subjects.flatMap(s => [
                        <td key={s} className={`px-8 py-5 text-center transition-all ${getSubjectCellStyle(h.period, s, selectedStudent.name)}`}>{h.scores[s] || '-'}</td>,
                        <td key={`${s}-rank`} className="px-4 py-5 text-center text-gray-500 font-medium">{allSubjectRanks[h.period]?.[s]?.[selectedStudent.name] || '-'}</td>
                      ])}
                      <td className="px-8 py-5 font-black text-indigo-600 text-right">{h.totalScore}</td>
                      <td className="px-8 py-5 text-center font-bold text-gray-600">{getStatusLabel(h.period, selectedStudent.name)}</td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </div>
        </>
      ) : (
        <div className="bg-white py-20 rounded-3xl border border-gray-100 shadow-sm text-center"><h3 className="text-xl font-bold text-gray-800">Please select a student above</h3></div>
      )}
    </div>
  );
};

export default StudentDetailView;

import React, { useState, useMemo } from 'react';
import { Users, Layers, Target, Award, History, Crown, Calculator, Calendar, BarChart3, TrendingUp } from 'lucide-react';
import { AnalysisState } from '../types';
import { StatCard, TabButton } from './SharedComponents';
import * as AnalysisEngine from '../utils/analysisUtils';

// View Imports
import SchoolView from './SchoolView';
import ClassComparisonView from './ClassComparisonView';
import EliteBenchmarksView from './EliteBenchmarksView';
import ExamParametersView from './ExamParametersView';
import StudentDetailView from './StudentDetailView';
import SubjectAnalysisView from './SubjectAnalysisView';
import ProgressAnalysisView from './ProgressAnalysisView';

const colors = ['#3b82f6', '#10b981', '#f59e0b', '#ef4444', '#8b5cf6', '#ec4899', '#06b6d4', '#f97316'];

const Dashboard: React.FC<{ data: AnalysisState }> = ({ data }) => {
  const [activeTab, setActiveTab] = useState<'school' | 'comparison' | 'kings' | 'subjectAnalysis' | 'parameters' | 'student' | 'progress'>('school');

  const allPeriods = useMemo(() => 
    data.students[0]?.history.map(h => h.period) || [], 
    [data.students]
  );

  const [selectedPeriod, setSelectedPeriod] = useState<string>(allPeriods[allPeriods.length - 1] || '');
  const [selectedClasses, setSelectedClasses] = useState<string[]>([data.classes[0]]);
  const [benchmarkClass, setBenchmarkClass] = useState(data.classes[0]);
  const [selectedStudentId, setSelectedStudentId] = useState(data.students[0]?.id);

  const [studentSearchTerm, setStudentSearchTerm] = useState('');
  const [classFilter, setClassFilter] = useState<string>('all');

  const [thresholdType, setThresholdType] = useState<'rank' | 'percent'>('rank');
  const [manualThresholds, setManualThresholds] = useState<Record<string, number>>({
    '清北': 5, 'C9': 30, '高分数': 100, '名校': 300, '特控': 600,
  });

  const admissionLabels = [
    { key: '清北', color: '#be123c' },
    { key: 'C9', color: '#1e40af' },
    { key: '高分数', color: '#0369a1' },
    { key: '名校', color: '#0d9488' },
    { key: '特控', color: '#10b981' },
  ];

  const allHistoricalRanks = useMemo(() => 
    AnalysisEngine.calculateHistoricalRanks(data.students), 
    [data.students]
  );

  const allSubjectRanks = useMemo(() => 
    AnalysisEngine.calculateSubjectHistoricalRanks(data.students, data.subjects),
    [data.students, data.subjects]
  );

  const gradeAveragesByPeriod = useMemo(() => 
    AnalysisEngine.calculateGradeAverages(data.students), 
    [data.students]
  );

  const periodData = useMemo(() => 
    AnalysisEngine.getPeriodSnapshot(data.students, selectedPeriod, allHistoricalRanks),
    [data.students, selectedPeriod, allHistoricalRanks]
  );

  // Added missing data calculations for comparison and kings views to fix compilation errors
  const classComparisonData = useMemo(() => {
    return data.subjects.map(sub => {
      const row: any = { name: sub };
      data.classes.forEach(cls => {
        const clsStudents = periodData.filter(s => s.class === cls);
        const avg = clsStudents.length > 0 
          ? clsStudents.reduce((acc, s) => acc + (s.currentScores[sub] || 0), 0) / clsStudents.length 
          : 0;
        row[cls] = parseFloat(avg.toFixed(2));
      });
      return row;
    });
  }, [data.subjects, data.classes, periodData]);

  const rankingDistributionData = useMemo(() => {
    const brackets = [
      { name: 'Top 10', limit: 10 },
      { name: 'Top 50', limit: 50 },
      { name: 'Top 100', limit: 100 },
      { name: 'Top 300', limit: 300 }
    ];
    return brackets.map(b => {
      const row: any = { name: b.name };
      data.classes.forEach(cls => {
        row[cls] = periodData.filter(s => s.class === cls && s.periodSchoolRank <= b.limit).length;
      });
      return row;
    });
  }, [data.classes, periodData]);

  const kingsData = useMemo(() => {
    return data.subjects.map(sub => {
      const classStudents = periodData.filter(s => s.class === benchmarkClass);
      const classMax = classStudents.length > 0 ? Math.max(...classStudents.map(s => s.currentScores[sub] || 0)) : 0;
      const gradeMax = periodData.length > 0 ? Math.max(...periodData.map(s => s.currentScores[sub] || 0)) : 0;
      return { subject: sub, classMax, gradeMax };
    });
  }, [data.subjects, periodData, benchmarkClass]);

  const duelData = useMemo(() => {
    return data.subjects.map(sub => {
      const classStudents = periodData.filter(s => s.class === benchmarkClass);
      const classMax = classStudents.length > 0 ? Math.max(...classStudents.map(s => s.currentScores[sub] || 0)) : 0;
      const schoolFirst = periodData.length > 0 ? Math.max(...periodData.map(s => s.currentScores[sub] || 0)) : 0;
      return { subject: sub, classFirst: classMax, schoolFirst };
    });
  }, [data.subjects, periodData, benchmarkClass]);

  const hasImportedStatus = useMemo(() => 
    periodData.some(s => s.currentStatus !== undefined && s.currentStatus !== ''),
    [periodData]
  );

  // 获取总分基数用于阈值推算
  const totalCohortSize = useMemo(() => 
    AnalysisEngine.getEffectiveCohortSize(selectedPeriod, null, periodData, {}, allHistoricalRanks),
    [selectedPeriod, periodData, allHistoricalRanks]
  );

  const thresholds = useMemo(() => {
    if (hasImportedStatus) {
      return AnalysisEngine.deriveThresholdsFromMetadata(periodData, admissionLabels, totalCohortSize);
    }
    return manualThresholds;
  }, [hasImportedStatus, periodData, totalCohortSize, manualThresholds]);

  const effectiveThresholdType = hasImportedStatus ? 'percent' : thresholdType;

  const examParameters = useMemo(() => 
    AnalysisEngine.calculateExamParameters(periodData, data.subjects),
    [periodData, data.subjects]
  );

  const aboveLineCount = useMemo(() => {
    if (hasImportedStatus) {
      const validLabels = ['清北', 'C9', '高分', '名校', '特控', '上线', '一本', '本科'];
      return periodData.filter(s => {
        const status = s.currentStatus || '';
        return status !== '' && status !== '未上线' && validLabels.some(label => status.includes(label));
      }).length;
    }

    const limit = effectiveThresholdType === 'rank' 
      ? (thresholds['特控'] || 0) 
      : Math.round(((thresholds['特控'] || 0) / 100) * totalCohortSize);
    return periodData.filter(s => s.periodSchoolRank <= limit).length;
  }, [periodData, thresholds, effectiveThresholdType, hasImportedStatus, totalCohortSize]);

  return (
    <div className="space-y-8 animate-in fade-in duration-700 pb-12">
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <StatCard icon={<Users className="w-5 h-5 text-blue-600" />} title="Students in File" value={data.students.length.toString()} subtitle="Current Sample" />
        <StatCard icon={<Layers className="w-5 h-5 text-green-600" />} title="Classes" value={data.classes.length.toString()} subtitle="Active Groups" />
        <StatCard icon={<Target className="w-5 h-5 text-purple-600" />} title="上线人数" value={aboveLineCount.toString()} subtitle={`Based on ${selectedPeriod}`} />
        <StatCard icon={<Award className="w-5 h-5 text-orange-600" />} title="Grade Size (Est)" value={totalCohortSize.toString()} subtitle="Computed Cohort Size" />
      </div>

      <div className="flex flex-col lg:flex-row gap-4 items-start lg:items-center justify-between">
        <div className="flex flex-wrap gap-1 bg-white p-1.5 rounded-2xl shadow-sm border border-gray-100 w-fit">
          <TabButton active={activeTab === 'school'} onClick={() => setActiveTab('school')} icon={<History className="w-4 h-4"/>} label="School View" />
          <TabButton active={activeTab === 'comparison'} onClick={() => setActiveTab('comparison')} icon={<Layers className="w-4 h-4"/>} label="Class Comparison" />
          <TabButton active={activeTab === 'kings'} onClick={() => setActiveTab('kings')} icon={<Crown className="w-4 h-4"/>} label="Elite Benchmarks" />
          <TabButton active={activeTab === 'parameters'} onClick={() => setActiveTab('parameters')} icon={<Calculator className="w-4 h-4"/>} label="Exam Parameters" />
          <TabButton active={activeTab === 'subjectAnalysis'} onClick={() => setActiveTab('subjectAnalysis')} icon={<BarChart3 className="w-4 h-4"/>} label="Subject Analysis" />
          <TabButton active={activeTab === 'progress'} onClick={() => setActiveTab('progress')} icon={<TrendingUp className="w-4 h-4"/>} label="Progress Analysis" />
          <TabButton active={activeTab === 'student'} onClick={() => setActiveTab('student')} icon={<Target className="w-4 h-4"/>} label="Student Detail" />
        </div>
        <div className="flex items-center gap-3 bg-blue-50/50 px-4 py-2 rounded-2xl border border-blue-100 animate-in slide-in-from-right-4">
          <Calendar className="w-4 h-4 text-blue-600" />
          <select className="bg-transparent border-none text-sm font-black text-blue-900 focus:ring-0 cursor-pointer" value={selectedPeriod} onChange={(e) => setSelectedPeriod(e.target.value)}>
            {allPeriods.map(p => <option key={p} value={p}>{p}</option>)}
          </select>
        </div>
      </div>

      <div className="w-full">
        {activeTab === 'school' && (
          <SchoolView 
            selectedPeriod={selectedPeriod} 
            periodData={periodData} 
            subjects={data.subjects} 
            thresholds={thresholds} 
            setThresholds={setManualThresholds} 
            thresholdType={effectiveThresholdType} 
            setThresholdType={setThresholdType} 
            hasImportedStatus={hasImportedStatus} 
            totalStudents={totalCohortSize}
            allHistoricalRanks={allHistoricalRanks}
          />
        )}
        {activeTab === 'comparison' && <ClassComparisonView selectedPeriod={selectedPeriod} classes={data.classes} selectedClasses={selectedClasses} setSelectedClasses={setSelectedClasses} classComparisonData={classComparisonData} rankingDistributionData={rankingDistributionData} colors={colors} periodData={periodData} />}
        {activeTab === 'kings' && <EliteBenchmarksView selectedPeriod={selectedPeriod} classes={data.classes} benchmarkClass={benchmarkClass} setBenchmarkClass={setBenchmarkClass} kingsData={kingsData} duelData={duelData} />}
        {activeTab === 'parameters' && <ExamParametersView selectedPeriod={selectedPeriod} examParameters={examParameters} colors={colors} totalParticipants={periodData.length} />}
        {activeTab === 'subjectAnalysis' && (
          <SubjectAnalysisView 
            selectedPeriod={selectedPeriod}
            periodData={periodData}
            subjects={data.subjects}
            classes={data.classes}
            allSubjectRanks={allSubjectRanks}
            allHistoricalRanks={allHistoricalRanks}
            thresholds={thresholds}
            thresholdType={effectiveThresholdType}
          />
        )}
        {activeTab === 'progress' && <ProgressAnalysisView students={data.students} allPeriods={allPeriods} allHistoricalRanks={allHistoricalRanks} classes={data.classes} />}
        {activeTab === 'student' && (
          <StudentDetailView 
            studentSearchTerm={studentSearchTerm} setStudentSearchTerm={setStudentSearchTerm} 
            classFilter={classFilter} setClassFilter={setClassFilter} classes={data.classes} 
            selectableStudents={data.students.filter(s => s.name.toLowerCase().includes(studentSearchTerm.toLowerCase()) && (classFilter === 'all' || s.class === classFilter))} 
            selectedStudentId={selectedStudentId} setSelectedStudentId={setSelectedStudentId} 
            selectedStudent={data.students.find(s => s.id === selectedStudentId)} 
            subjects={data.subjects} gradeAveragesByPeriod={gradeAveragesByPeriod} 
            allHistoricalRanks={allHistoricalRanks}
            allSubjectRanks={allSubjectRanks}
            thresholds={thresholds}
            thresholdType={effectiveThresholdType}
            totalStudents={totalCohortSize}
            selectedPeriod={selectedPeriod}
            periodData={periodData}
          />
        )}
      </div>
    </div>
  );
};

export default Dashboard;

import { StudentRecord, ScoreSnapshot } from '../types';

/**
 * 获取特定周期、特定科目的名次计算基数（分母）
 * 如果存在导入的名次，则取最大名次值；否则取当前样本总数
 */
export const getEffectiveCohortSize = (
  period: string,
  subject: string | null, // null 表示总分
  periodData: any[],
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>,
  allHistoricalRanks: Record<string, Record<string, number>>
): number => {
  let maxRankFound = 0;

  if (subject) {
    // 处理单科名次基数
    const subRanks = allSubjectRanks[period]?.[subject] || {};
    const values = Object.values(subRanks);
    if (values.length > 0) {
      maxRankFound = Math.max(...values);
    }
  } else {
    // 处理总分名次基数
    const totalRanks = allHistoricalRanks[period] || {};
    const values = Object.values(totalRanks);
    if (values.length > 0) {
      maxRankFound = Math.max(...values);
    }
  }

  // 基数至少是当前文件内的学生数，防止数据异常
  return Math.max(periodData.length, maxRankFound);
};

/**
 * 计算全周期总分名次映射
 */
export const calculateHistoricalRanks = (students: StudentRecord[]) => {
  const allPeriods = Array.from(new Set(students.flatMap(s => s.history.map(h => h.period))));
  const periodRankMap: Record<string, Record<string, number>> = {};

  allPeriods.forEach(period => {
    const hasImportedRanks = students.some(s => {
      const h = s.history.find(p => p.period === period);
      return h?.schoolRank !== undefined && h.schoolRank > 0;
    });

    if (hasImportedRanks) {
      const ranks: Record<string, number> = {};
      students.forEach(s => {
        const h = s.history.find(p => p.period === period);
        if (h && h.schoolRank) ranks[s.name] = h.schoolRank;
      });
      if (Object.keys(ranks).length > 0) {
        periodRankMap[period] = ranks;
        return;
      }
    }

    const periodStudents = students
      .map(s => ({
        name: s.name,
        total: s.history.find(h => h.period === period)?.totalScore ?? -1
      }))
      .filter(s => s.total !== -1)
      .sort((a, b) => b.total - a.total);

    const ranks: Record<string, number> = {};
    periodStudents.forEach((s, idx) => {
      ranks[s.name] = idx + 1;
    });
    periodRankMap[period] = ranks;
  });

  return periodRankMap;
};

/**
 * 计算全周期、全科目的名次映射
 */
export const calculateSubjectHistoricalRanks = (students: StudentRecord[], subjects: string[]) => {
  const allPeriods = Array.from(new Set(students.flatMap(s => s.history.map(h => h.period))));
  const result: Record<string, Record<string, Record<string, number>>> = {};

  allPeriods.forEach(period => {
    result[period] = {};
    subjects.forEach(sub => {
      const hasImportedRanks = students.some(s => {
        const h = s.history.find(p => p.period === period);
        return h?.ranks?.[sub] !== undefined && h.ranks[sub] > 0;
      });

      if (hasImportedRanks) {
        const subRanks: Record<string, number> = {};
        students.forEach(s => {
          const h = s.history.find(p => p.period === period);
          if (h?.ranks?.[sub]) subRanks[s.name] = h.ranks[sub];
        });
        if (Object.keys(subRanks).length > 0) {
          result[period][sub] = subRanks;
          return;
        }
      }

      const subRanks: Record<string, number> = {};
      const sortedStudents = students
        .map(s => ({
          name: s.name,
          score: s.history.find(h => h.period === period)?.scores[sub] ?? -1
        }))
        .filter(s => s.score !== -1)
        .sort((a, b) => b.score - a.score);

      sortedStudents.forEach((s, idx) => {
        subRanks[s.name] = idx + 1;
      });
      result[period][sub] = subRanks;
    });
  });

  return result;
};

/**
 * 根据导入的 Metadata 自动推算名次百分比阈值
 */
export const deriveThresholdsFromMetadata = (
  periodData: any[], 
  labels: { key: string, color: string }[],
  cohortSize: number
): Record<string, number> => {
  const derived: Record<string, number> = {};
  if (cohortSize === 0) return derived;

  let cumulativeCount = 0;
  labels.forEach(label => {
    const count = periodData.filter(s => {
      const status = (s.currentStatus || '').trim();
      return status === label.key || status.includes(label.key);
    }).length;

    cumulativeCount += count;
    // 这里的推算目前还是基于样本内的分布，因为元数据 status 是样本自带的
    // 我们将其存为相对于 cohortSize 的百分比
    derived[label.key] = parseFloat(((cumulativeCount / periodData.length) * 100).toFixed(4));
  });

  return derived;
};

/**
 * 获取特定考试周期的快照数据
 */
export const getPeriodSnapshot = (students: StudentRecord[], selectedPeriod: string, allHistoricalRanks: Record<string, Record<string, number>>) => {
  if (!selectedPeriod) return [];
  const ranks = allHistoricalRanks[selectedPeriod] || {};
  return students.map(s => {
    const historyItem = s.history.find(h => h.period === selectedPeriod);
    return {
      ...s,
      currentTotal: historyItem?.totalScore || 0,
      currentAverage: historyItem?.averageScore || 0,
      currentScores: historyItem?.scores || {},
      currentStatus: historyItem?.status,
      periodSchoolRank: ranks[s.name] || historyItem?.schoolRank || 9999
    };
  }).sort((a, b) => a.periodSchoolRank - b.periodSchoolRank);
};

/**
 * 计算总分上线分布
 */
export const getAdmissionDistribution = (
  period: string,
  periodData: any[],
  thresholds: Record<string, number>,
  thresholdType: 'rank' | 'percent',
  labels: { key: string, color: string }[],
  allHistoricalRanks: Record<string, Record<string, number>>
) => {
  if (!periodData.length) return [];

  const hasImportedStatus = periodData.some(s => s.currentStatus !== undefined && s.currentStatus !== '');

  if (hasImportedStatus) {
    const statusCounts: Record<string, number> = {};
    periodData.forEach(s => {
      const status = (s.currentStatus || '未上线').trim();
      statusCounts[status] = (statusCounts[status] || 0) + 1;
    });

    const results = labels.map(l => ({
      name: l.key,
      value: statusCounts[l.key] || 0,
      color: l.color
    })).filter(r => r.value > 0);

    const otherCount = periodData.length - results.reduce((acc, r) => acc + r.value, 0);
    if (otherCount > 0) {
      results.push({ name: '未上线', value: otherCount, color: '#94a3b8' });
    }
    return results;
  }

  // 关键修正：使用总分名次基数
  const cohortSize = getEffectiveCohortSize(period, null, periodData, {}, allHistoricalRanks);

  const sortedThresholds = [...labels].map(l => ({
    ...l,
    limit: thresholdType === 'rank' 
      ? thresholds[l.key] 
      : Math.round((thresholds[l.key] / 100) * cohortSize)
  })).sort((a, b) => a.limit - b.limit);

  const results = sortedThresholds.map((t, idx) => {
    const prevLimit = idx === 0 ? 0 : sortedThresholds[idx - 1].limit;
    const count = periodData.filter(s => s.periodSchoolRank > prevLimit && s.periodSchoolRank <= t.limit).length;
    return { name: t.key, value: count, color: t.color };
  });

  const lastLimit = sortedThresholds[sortedThresholds.length - 1].limit;
  results.push({
    name: '未上线',
    value: periodData.filter(s => s.periodSchoolRank > lastLimit).length,
    color: '#94a3b8'
  });

  return results.filter(r => r.value > 0);
};

/**
 * 单科上线分布核心逻辑
 */
export const getSubjectDistribution = (
  selectedPeriod: string,
  subject: string,
  selectedClasses: string[],
  periodData: any[],
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>,
  allHistoricalRanks: Record<string, Record<string, number>>,
  thresholds: Record<string, number>,
  thresholdType: 'rank' | 'percent'
) => {
  const filteredData = periodData.filter(s => selectedClasses.includes(s.class));
  const subjectRanks = allSubjectRanks[selectedPeriod]?.[subject] || {};

  // 核心：基于该科目的年级名次最大值来计算基数
  const cohortSize = getEffectiveCohortSize(selectedPeriod, subject, periodData, allSubjectRanks, allHistoricalRanks);

  const labels = [
    { key: '清北', color: '#be123c' },
    { key: 'C9', color: '#1e40af' },
    { key: '高分数', color: '#0369a1' },
    { key: '名校', color: '#0d9488' },
    { key: '特控', color: '#10b981' },
  ];

  const results = labels.map((l, idx) => {
    const limit = thresholdType === 'rank' 
      ? thresholds[l.key] 
      : Math.round((thresholds[l.key] / 100) * cohortSize);

    const prevLimit = idx === 0 ? 0 : (thresholdType === 'rank' 
      ? thresholds[labels[idx-1].key] 
      : Math.round((thresholds[labels[idx-1].key] / 100) * cohortSize));

    const count = filteredData.filter(s => {
      const rank = subjectRanks[s.name];
      return rank !== undefined && rank > prevLimit && rank <= limit;
    }).length;

    return { name: l.key, count, color: l.color };
  });

  const maxLimit = thresholdType === 'rank' 
    ? thresholds[labels[labels.length - 1].key] 
    : Math.round((thresholdType === 'rank' ? thresholds[labels[labels.length - 1].key] : (thresholds[labels[labels.length - 1].key] / 100) * cohortSize));

  results.push({
    name: '未上线',
    count: filteredData.filter(s => {
      const rank = subjectRanks[s.name];
      return rank !== undefined && rank > maxLimit;
    }).length,
    color: '#94a3b8'
  });

  return results.filter(r => r.count > 0);
};

/**
 * 获取特定科目关注名单
 */
export const getBelowLineStudents = (
  selectedPeriod: string,
  subject: string,
  selectedClasses: string[],
  periodData: any[],
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>,
  allHistoricalRanks: Record<string, Record<string, number>>,
  teKongThreshold: number,
  thresholdType: 'rank' | 'percent' = 'rank'
) => {
  const subjectRanks = allSubjectRanks[selectedPeriod]?.[subject] || {};
  const filteredData = periodData.filter(s => selectedClasses.includes(s.class));
  const cohortSize = getEffectiveCohortSize(selectedPeriod, subject, periodData, allSubjectRanks, allHistoricalRanks);

  const effectiveLimit = thresholdType === 'percent' 
    ? Math.round((teKongThreshold / 100) * cohortSize)
    : teKongThreshold;

  return filteredData
    .filter(s => {
      const rank = subjectRanks[s.name];
      return rank !== undefined && rank > effectiveLimit;
    })
    .map(s => ({
      name: s.name,
      class: s.class,
      rank: subjectRanks[s.name]
    }))
    .sort((a, b) => (a.rank as number) - (b.rank as number));
};

/**
 * 获取单科排名等级样式
 */
export const getSubjectRankCategory = (
  rank: number,
  thresholds: Record<string, number>,
  thresholdType: 'rank' | 'percent',
  cohortSize: number
) => {
  const categories = [
    { key: '清北', type: 'king' },
    { key: 'C9', type: 'elite' },
    { key: '高分数', type: 'high' },
    { key: '名校', type: 'standard' },
    { key: '特控', type: 'pass' },
  ];

  for (const cat of categories) {
    const limit = thresholdType === 'rank' 
      ? thresholds[cat.key] 
      : Math.round((thresholds[cat.key] / 100) * cohortSize);

    if (rank <= limit) return cat.type;
  }
  return 'fail';
};

export const calculateProgressCoefficient = (x: number, y: number): number => {
  if (x <= 0 || y <= 0) return 0;
  return parseFloat(((2 * (x - y)) / (x + y)).toFixed(2));
};

export const getProgressAnalysisData = (students: StudentRecord[], periodX: string, periodY: string, allHistoricalRanks: Record<string, Record<string, number>>) => {
  if (!periodX || !periodY) return [];
  const ranksX = allHistoricalRanks[periodX] || {};
  const ranksY = allHistoricalRanks[periodY] || {};

  return students.map(s => {
    const x = ranksX[s.name];
    const y = ranksY[s.name];
    if (x === undefined || y === undefined) return null;
    const coefficient = calculateProgressCoefficient(x, y);
    const streakInfo = calculateStreakInfo(s, allHistoricalRanks);
    return {
      name: s.name,
      class: s.class,
      rankX: x,
      rankY: y,
      rankChange: x - y,
      coefficient,
      streakCount: streakInfo ? (streakInfo.type === 'improvement' ? streakInfo.count : -streakInfo.count) : 0
    };
  }).filter((d): d is NonNullable<typeof d> => d !== null);
};

export const calculateGradeAverages = (students: StudentRecord[]) => {
  const allPeriods = Array.from(new Set(students.flatMap(s => s.history.map(h => h.period))));
  const averages: Record<string, number> = {};
  allPeriods.forEach(period => {
    const totals = students.map(s => s.history.find(h => h.period === period)?.totalScore).filter((t): t is number => t !== undefined);
    if (totals.length > 0) averages[period] = totals.reduce((a, b) => a + b, 0) / totals.length;
  });
  return averages;
};

export const calculateStreakInfo = (student: StudentRecord, allHistoricalRanks: Record<string, Record<string, number>>) => {
  const studentName = student.name;
  const rankList: number[] = student.history.map(h => allHistoricalRanks[h.period]?.[studentName]).filter((r): r is number => r !== undefined);
  if (rankList.length < 2) return null;
  const last = rankList[rankList.length - 1];
  const prev = rankList[rankList.length - 2];
  if (last === prev) return { count: 0, type: 'stable', totalChange: 0, steps: [] };
  const isImproving = last < prev;
  const type = isImproving ? 'improvement' : 'decline';
  let count = 0, totalChange = 0;
  const steps: number[] = [];
  for (let i = rankList.length - 1; i > 0; i--) {
    const current = rankList[i], previous = rankList[i - 1], diff = previous - current;
    if ((isImproving && diff > 0) || (!isImproving && diff < 0)) {
      count++;
      totalChange += diff;
      steps.unshift(diff);
    } else break;
  }
  return { count, type, totalChange, steps };
};

export const getAdmissionCategory = (rank: number, thresholds: Record<string, number>, thresholdType: 'rank' | 'percent', cohortSize: number, snapshotStatus?: string) => {
  if (snapshotStatus && snapshotStatus !== '' && snapshotStatus !== '未上线') return snapshotStatus;
  const lines = [{ key: '清北', label: '清北' }, { key: 'C9', label: 'C9' }, { key: '高分数', label: '高分' }, { key: '名校', label: '名校' }, { key: '特控', label: '特控' }];
  for (const line of lines) {
    const limit = thresholdType === 'rank' ? thresholds[line.key] : Math.round((thresholds[line.key] / 100) * cohortSize);
    if (rank <= limit) return line.label;
  }
  return '未上线';
};

export const calculateExamParameters = (periodData: any[], subjects: string[]) => {
  if (periodData.length === 0) return null;
  const n = periodData.length, stats: any[] = [];
  subjects.forEach(sub => {
    const scores = periodData.map(s => s.currentScores[sub] || 0).sort((a, b) => a - b);
    const sum = scores.reduce((a, b) => a + b, 0), mean = sum / n, max = scores[n - 1];
    let fullScore = max > 120 ? (max > 150 ? Math.ceil(max / 10) * 10 : 150) : (max > 100 ? 120 : 100);
    const variance = scores.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / n;
    const stdDev = Math.sqrt(variance), median = n % 2 === 0 ? (scores[n/2 - 1] + scores[n/2]) / 2 : scores[Math.floor(n/2)];

    // 众数 (Mode) 计算逻辑
    const frequency: Record<number, number> = {};
    let maxFreq = 0;
    scores.forEach(s => {
      frequency[s] = (frequency[s] || 0) + 1;
      if (frequency[s] > maxFreq) maxFreq = frequency[s];
    });
    const modeValues = Object.keys(frequency)
      .filter(score => frequency[Number(score)] === maxFreq)
      .map(Number);
    const mode = maxFreq > 1 ? modeValues.join(', ') : '无';

    const difficulty = mean / fullScore;
    const splitIdx = Math.round(n * 0.27), top27 = scores.slice(n - splitIdx), bottom27 = scores.slice(0, splitIdx);
    const meanTop = top27.length > 0 ? top27.reduce((a, b) => a + b, 0) / top27.length : 0;
    const meanBottom = bottom27.length > 0 ? bottom27.reduce((a, b) => a + b, 0) / bottom27.length : 0;
    const discrimination = (meanTop - meanBottom) / fullScore;

    stats.push({ 
      subject: sub, 
      participants: n, 
      max, 
      mean: parseFloat(mean.toFixed(2)), 
      stdDev: parseFloat(stdDev.toFixed(2)), 
      difficulty: parseFloat(difficulty.toFixed(2)), 
      discrimination: parseFloat(discrimination.toFixed(2)), 
      variance, 
      median,
      mode 
    });
  });
  const k = subjects.length, sumVarItems = stats.reduce((acc, s) => acc + s.variance, 0);
  const totalScores = periodData.map(s => s.currentTotal), meanTotal = totalScores.reduce((a, b) => a + b, 0) / n;
  const varTotal = totalScores.reduce((a, b) => a + Math.pow(b - meanTotal, 2), 0) / n;
  const reliability = k > 1 ? (k / (k - 1)) * (1 - (sumVarItems / varTotal)) : 1;
  return { subjectStats: stats, reliability: parseFloat(reliability.toFixed(2)) };
};

export const getStudentRadarData = (student: StudentRecord, selectedPeriod: string, subjects: string[], radarBaseline: 'class' | 'grade', periodData: any[]) => {
  const currentScores = student.history.find(h => h.period === selectedPeriod)?.scores || {};
  const baselineSource = radarBaseline === 'class' ? periodData.filter(s => s.class === student.class) : periodData;
  return subjects.map(sub => ({
    subject: sub,
    score: currentScores[sub] || 0,
    baseline: parseFloat((baselineSource.length > 0 ? baselineSource.reduce((acc, s) => acc + (s.currentScores?.[sub] || 0), 0) / baselineSource.length : 0).toFixed(1)),
    fullMark: 150
  }));
};

export const getStudentSubjectTrend = (student: StudentRecord, subject: string, allSubjectRanks: Record<string, Record<string, Record<string, number>>>) => {
  return student.history.map(h => ({ period: h.period, rank: allSubjectRanks[h.period]?.[subject]?.[student.name] || null })).filter(d => d.rank !== null);
};

export const getSubjectAverages = (periodData: any[], subjects: string[]) => {
  return subjects.map(sub => ({ name: sub, avg: parseFloat((periodData.reduce((acc, s) => acc + (s.currentScores[sub] || 0), 0) / periodData.length).toFixed(2)) }));
};

export const getClassSummaries = (periodData: any[], selectedClasses: string[]) => {
  return selectedClasses.map(cls => {
    const clsStudents = periodData.filter(s => s.class === cls);
    const totalAvg = clsStudents.length > 0 ? clsStudents.reduce((acc, s) => acc + s.currentTotal, 0) / clsStudents.length : 0;
    const top10Count = clsStudents.filter(s => s.periodSchoolRank <= 10).length;
    const top50Count = clsStudents.filter(s => s.periodSchoolRank <= 50).length;
    return { className: cls, count: clsStudents.length, average: parseFloat(totalAvg.toFixed(2)), top10: top10Count, top50: top50Count };
  });
};

export const getClassLeaderboard = (classSummaries: any[]) => {
  if (classSummaries.length === 0) return null;
  return {
    highestAvg: [...classSummaries].sort((a, b) => b.average - a.average)[0],
    mostTop10: [...classSummaries].sort((a, b) => b.top10 - a.top10)[0],
    mostTop50: [...classSummaries].sort((a, b) => b.top50 - a.top50)[0],
  };
};

export const calculateHeatmapMaxValues = (data: any[], selectedClasses: string[]) => {
  const map: Record<string, number> = {};
  data.forEach(row => { map[row.name] = Math.max(...selectedClasses.map(cls => row[cls] || 0)); });
  return map;
};

import { StudentRecord, ScoreSnapshot } from '../types';

/**
 * 获取特定周期、特定科目的名次计算基数（分母）
 * 如果存在导入的名次，则取最大名次值；否则取当前样本总数
 */
export const getEffectiveCohortSize = (
  period: string,
  subject: string | null, // null 表示总分
  periodData: any[],
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>,
  allHistoricalRanks: Record<string, Record<string, number>>
): number => {
  let maxRankFound = 0;

  if (subject) {
    // 处理单科名次基数
    const subRanks = allSubjectRanks[period]?.[subject] || {};
    const values = Object.values(subRanks);
    if (values.length > 0) {
      maxRankFound = Math.max(...values);
    }
  } else {
    // 处理总分名次基数
    const totalRanks = allHistoricalRanks[period] || {};
    const values = Object.values(totalRanks);
    if (values.length > 0) {
      maxRankFound = Math.max(...values);
    }
  }

  // 基数至少是当前文件内的学生数，防止数据异常
  return Math.max(periodData.length, maxRankFound);
};

/**
 * 计算全周期总分名次映射
 */
export const calculateHistoricalRanks = (students: StudentRecord[]) => {
  const allPeriods = Array.from(new Set(students.flatMap(s => s.history.map(h => h.period))));
  const periodRankMap: Record<string, Record<string, number>> = {};

  allPeriods.forEach(period => {
    const hasImportedRanks = students.some(s => {
      const h = s.history.find(p => p.period === period);
      return h?.schoolRank !== undefined && h.schoolRank > 0;
    });

    if (hasImportedRanks) {
      const ranks: Record<string, number> = {};
      students.forEach(s => {
        const h = s.history.find(p => p.period === period);
        if (h && h.schoolRank) ranks[s.name] = h.schoolRank;
      });
      if (Object.keys(ranks).length > 0) {
        periodRankMap[period] = ranks;
        return;
      }
    }

    const periodStudents = students
      .map(s => ({
        name: s.name,
        total: s.history.find(h => h.period === period)?.totalScore ?? -1
      }))
      .filter(s => s.total !== -1)
      .sort((a, b) => b.total - a.total);

    const ranks: Record<string, number> = {};
    periodStudents.forEach((s, idx) => {
      ranks[s.name] = idx + 1;
    });
    periodRankMap[period] = ranks;
  });

  return periodRankMap;
};

/**
 * 计算全周期、全科目的名次映射
 */
export const calculateSubjectHistoricalRanks = (students: StudentRecord[], subjects: string[]) => {
  const allPeriods = Array.from(new Set(students.flatMap(s => s.history.map(h => h.period))));
  const result: Record<string, Record<string, Record<string, number>>> = {};

  allPeriods.forEach(period => {
    result[period] = {};
    subjects.forEach(sub => {
      const hasImportedRanks = students.some(s => {
        const h = s.history.find(p => p.period === period);
        return h?.ranks?.[sub] !== undefined && h.ranks[sub] > 0;
      });

      if (hasImportedRanks) {
        const subRanks: Record<string, number> = {};
        students.forEach(s => {
          const h = s.history.find(p => p.period === period);
          if (h?.ranks?.[sub]) subRanks[s.name] = h.ranks[sub];
        });
        if (Object.keys(subRanks).length > 0) {
          result[period][sub] = subRanks;
          return;
        }
      }

      const subRanks: Record<string, number> = {};
      const sortedStudents = students
        .map(s => ({
          name: s.name,
          score: s.history.find(h => h.period === period)?.scores[sub] ?? -1
        }))
        .filter(s => s.score !== -1)
        .sort((a, b) => b.score - a.score);

      sortedStudents.forEach((s, idx) => {
        subRanks[s.name] = idx + 1;
      });
      result[period][sub] = subRanks;
    });
  });

  return result;
};

/**
 * 根据导入的 Metadata 自动推算名次百分比阈值
 */
export const deriveThresholdsFromMetadata = (
  periodData: any[], 
  labels: { key: string, color: string }[],
  cohortSize: number
): Record<string, number> => {
  const derived: Record<string, number> = {};
  if (cohortSize === 0) return derived;

  let cumulativeCount = 0;
  labels.forEach(label => {
    const count = periodData.filter(s => {
      const status = (s.currentStatus || '').trim();
      return status === label.key || status.includes(label.key);
    }).length;

    cumulativeCount += count;
    // 这里的推算目前还是基于样本内的分布，因为元数据 status 是样本自带的
    // 我们将其存为相对于 cohortSize 的百分比
    derived[label.key] = parseFloat(((cumulativeCount / periodData.length) * 100).toFixed(4));
  });

  return derived;
};

/**
 * 获取特定考试周期的快照数据
 */
export const getPeriodSnapshot = (students: StudentRecord[], selectedPeriod: string, allHistoricalRanks: Record<string, Record<string, number>>) => {
  if (!selectedPeriod) return [];
  const ranks = allHistoricalRanks[selectedPeriod] || {};
  return students.map(s => {
    const historyItem = s.history.find(h => h.period === selectedPeriod);
    return {
      ...s,
      currentTotal: historyItem?.totalScore || 0,
      currentAverage: historyItem?.averageScore || 0,
      currentScores: historyItem?.scores || {},
      currentStatus: historyItem?.status,
      periodSchoolRank: ranks[s.name] || historyItem?.schoolRank || 9999
    };
  }).sort((a, b) => a.periodSchoolRank - b.periodSchoolRank);
};

/**
 * 计算总分上线分布
 */
export const getAdmissionDistribution = (
  period: string,
  periodData: any[],
  thresholds: Record<string, number>,
  thresholdType: 'rank' | 'percent',
  labels: { key: string, color: string }[],
  allHistoricalRanks: Record<string, Record<string, number>>
) => {
  if (!periodData.length) return [];

  const hasImportedStatus = periodData.some(s => s.currentStatus !== undefined && s.currentStatus !== '');

  if (hasImportedStatus) {
    const statusCounts: Record<string, number> = {};
    periodData.forEach(s => {
      const status = (s.currentStatus || '未上线').trim();
      statusCounts[status] = (statusCounts[status] || 0) + 1;
    });

    const results = labels.map(l => ({
      name: l.key,
      value: statusCounts[l.key] || 0,
      color: l.color
    })).filter(r => r.value > 0);

    const otherCount = periodData.length - results.reduce((acc, r) => acc + r.value, 0);
    if (otherCount > 0) {
      results.push({ name: '未上线', value: otherCount, color: '#94a3b8' });
    }
    return results;
  }

  // 关键修正：使用总分名次基数
  const cohortSize = getEffectiveCohortSize(period, null, periodData, {}, allHistoricalRanks);

  const sortedThresholds = [...labels].map(l => ({
    ...l,
    limit: thresholdType === 'rank' 
      ? thresholds[l.key] 
      : Math.round((thresholds[l.key] / 100) * cohortSize)
  })).sort((a, b) => a.limit - b.limit);

  const results = sortedThresholds.map((t, idx) => {
    const prevLimit = idx === 0 ? 0 : sortedThresholds[idx - 1].limit;
    const count = periodData.filter(s => s.periodSchoolRank > prevLimit && s.periodSchoolRank <= t.limit).length;
    return { name: t.key, value: count, color: t.color };
  });

  const lastLimit = sortedThresholds[sortedThresholds.length - 1].limit;
  results.push({
    name: '未上线',
    value: periodData.filter(s => s.periodSchoolRank > lastLimit).length,
    color: '#94a3b8'
  });

  return results.filter(r => r.value > 0);
};

/**
 * 单科上线分布核心逻辑
 */
export const getSubjectDistribution = (
  selectedPeriod: string,
  subject: string,
  selectedClasses: string[],
  periodData: any[],
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>,
  allHistoricalRanks: Record<string, Record<string, number>>,
  thresholds: Record<string, number>,
  thresholdType: 'rank' | 'percent'
) => {
  const filteredData = periodData.filter(s => selectedClasses.includes(s.class));
  const subjectRanks = allSubjectRanks[selectedPeriod]?.[subject] || {};

  // 核心：基于该科目的年级名次最大值来计算基数
  const cohortSize = getEffectiveCohortSize(selectedPeriod, subject, periodData, allSubjectRanks, allHistoricalRanks);

  const labels = [
    { key: '清北', color: '#be123c' },
    { key: 'C9', color: '#1e40af' },
    { key: '高分数', color: '#0369a1' },
    { key: '名校', color: '#0d9488' },
    { key: '特控', color: '#10b981' },
  ];

  const results = labels.map((l, idx) => {
    const limit = thresholdType === 'rank' 
      ? thresholds[l.key] 
      : Math.round((thresholds[l.key] / 100) * cohortSize);

    const prevLimit = idx === 0 ? 0 : (thresholdType === 'rank' 
      ? thresholds[labels[idx-1].key] 
      : Math.round((thresholds[labels[idx-1].key] / 100) * cohortSize));

    const count = filteredData.filter(s => {
      const rank = subjectRanks[s.name];
      return rank !== undefined && rank > prevLimit && rank <= limit;
    }).length;

    return { name: l.key, count, color: l.color };
  });

  // Fixed the unintentional nested comparison of thresholdType in maxLimit calculation.
  // In the 'else' branch where thresholdType is 'percent', the nested thresholdType === 'rank' check was redundant.
  const maxLimit = thresholdType === 'rank' 
    ? thresholds[labels[labels.length - 1].key] 
    : Math.round((thresholds[labels[labels.length - 1].key] / 100) * cohortSize);

  results.push({
    name: '未上线',
    count: filteredData.filter(s => {
      const rank = subjectRanks[s.name];
      return rank !== undefined && rank > maxLimit;
    }).length,
    color: '#94a3b8'
  });

  return results.filter(r => r.count > 0);
};

/**
 * 获取特定科目关注名单
 */
export const getBelowLineStudents = (
  selectedPeriod: string,
  subject: string,
  selectedClasses: string[],
  periodData: any[],
  allSubjectRanks: Record<string, Record<string, Record<string, number>>>,
  allHistoricalRanks: Record<string, Record<string, number>>,
  teKongThreshold: number,
  thresholdType: 'rank' | 'percent' = 'rank'
) => {
  const subjectRanks = allSubjectRanks[selectedPeriod]?.[subject] || {};
  const filteredData = periodData.filter(s => selectedClasses.includes(s.class));
  const cohortSize = getEffectiveCohortSize(selectedPeriod, subject, periodData, allSubjectRanks, allHistoricalRanks);

  const effectiveLimit = thresholdType === 'percent' 
    ? Math.round((teKongThreshold / 100) * cohortSize)
    : teKongThreshold;

  return filteredData
    .filter(s => {
      const rank = subjectRanks[s.name];
      return rank !== undefined && rank > effectiveLimit;
    })
    .map(s => ({
      name: s.name,
      class: s.class,
      rank: subjectRanks[s.name]
    }))
    .sort((a, b) => (a.rank as number) - (b.rank as number));
};

/**
 * 获取单科排名等级样式
 */
export const getSubjectRankCategory = (
  rank: number,
  thresholds: Record<string, number>,
  thresholdType: 'rank' | 'percent',
  cohortSize: number
) => {
  const categories = [
    { key: '清北', type: 'king' },
    { key: 'C9', type: 'elite' },
    { key: '高分数', type: 'high' },
    { key: '名校', type: 'standard' },
    { key: '特控', type: 'pass' },
  ];

  for (const cat of categories) {
    const limit = thresholdType === 'rank' 
      ? thresholds[cat.key] 
      : Math.round((thresholds[cat.key] / 100) * cohortSize);

    if (rank <= limit) return cat.type;
  }
  return 'fail';
};

export const calculateProgressCoefficient = (x: number, y: number): number => {
  if (x <= 0 || y <= 0) return 0;
  return parseFloat(((2 * (x - y)) / (x + y)).toFixed(2));
};

export const getProgressAnalysisData = (students: StudentRecord[], periodX: string, periodY: string, allHistoricalRanks: Record<string, Record<string, number>>) => {
  if (!periodX || !periodY) return [];
  const ranksX = allHistoricalRanks[periodX] || {};
  const ranksY = allHistoricalRanks[periodY] || {};

  return students.map(s => {
    const x = ranksX[s.name];
    const y = ranksY[s.name];
    if (x === undefined || y === undefined) return null;
    const coefficient = calculateProgressCoefficient(x, y);
    const streakInfo = calculateStreakInfo(s, allHistoricalRanks);
    return {
      name: s.name,
      class: s.class,
      rankX: x,
      rankY: y,
      rankChange: x - y,
      coefficient,
      streakCount: streakInfo ? (streakInfo.type === 'improvement' ? streakInfo.count : -streakInfo.count) : 0
    };
  }).filter((d): d is NonNullable<typeof d> => d !== null);
};

export const calculateGradeAverages = (students: StudentRecord[]) => {
  const allPeriods = Array.from(new Set(students.flatMap(s => s.history.map(h => h.period))));
  const averages: Record<string, number> = {};
  allPeriods.forEach(period => {
    const totals = students.map(s => s.history.find(h => h.period === period)?.totalScore).filter((t): t is number => t !== undefined);
    if (totals.length > 0) averages[period] = totals.reduce((a, b) => a + b, 0) / totals.length;
  });
  return averages;
};

export const calculateStreakInfo = (student: StudentRecord, allHistoricalRanks: Record<string, Record<string, number>>) => {
  const studentName = student.name;
  const rankList: number[] = student.history.map(h => allHistoricalRanks[h.period]?.[studentName]).filter((r): r is number => r !== undefined);
  if (rankList.length < 2) return null;
  const last = rankList[rankList.length - 1];
  const prev = rankList[rankList.length - 2];
  if (last === prev) return { count: 0, type: 'stable', totalChange: 0, steps: [] };
  const isImproving = last < prev;
  const type = isImproving ? 'improvement' : 'decline';
  let count = 0, totalChange = 0;
  const steps: number[] = [];
  for (let i = rankList.length - 1; i > 0; i--) {
    const current = rankList[i], previous = rankList[i - 1], diff = previous - current;
    if ((isImproving && diff > 0) || (!isImproving && diff < 0)) {
      count++;
      totalChange += diff;
      steps.unshift(diff);
    } else break;
  }
  return { count, type, totalChange, steps };
};

export const getAdmissionCategory = (rank: number, thresholds: Record<string, number>, thresholdType: 'rank' | 'percent', cohortSize: number, snapshotStatus?: string) => {
  if (snapshotStatus && snapshotStatus !== '' && snapshotStatus !== '未上线') return snapshotStatus;
  const lines = [{ key: '清北', label: '清北' }, { key: 'C9', label: 'C9' }, { key: '高分数', label: '高分' }, { key: '名校', label: '名校' }, { key: '特控', label: '特控' }];
  for (const line of lines) {
    const limit = thresholdType === 'rank' ? thresholds[line.key] : Math.round((thresholds[line.key] / 100) * cohortSize);
    if (rank <= limit) return line.label;
  }
  return '未上线';
};

export const calculateExamParameters = (periodData: any[], subjects: string[]) => {
  if (periodData.length === 0) return null;
  const n = periodData.length, stats: any[] = [];
  subjects.forEach(sub => {
    const scores = periodData.map(s => s.currentScores[sub] || 0).sort((a, b) => a - b);
    const sum = scores.reduce((a, b) => a + b, 0), mean = sum / n, max = scores[n - 1];
    let fullScore = max > 120 ? (max > 150 ? Math.ceil(max / 10) * 10 : 150) : (max > 100 ? 120 : 100);
    const variance = scores.reduce((a, b) => a + Math.pow(b - mean, 2), 0) / n;
    const stdDev = Math.sqrt(variance), median = n % 2 === 0 ? (scores[n/2 - 1] + scores[n/2]) / 2 : scores[Math.floor(n/2)];

    // 众数 (Mode) 计算逻辑
    const frequency: Record<number, number> = {};
    let maxFreq = 0;
    scores.forEach(s => {
      frequency[s] = (frequency[s] || 0) + 1;
      if (frequency[s] > maxFreq) maxFreq = frequency[s];
    });
    const modeValues = Object.keys(frequency)
      .filter(score => frequency[Number(score)] === maxFreq)
      .map(Number);
    const mode = maxFreq > 1 ? modeValues.join(', ') : '无';

    const difficulty = mean / fullScore;
    const splitIdx = Math.round(n * 0.27), top27 = scores.slice(n - splitIdx), bottom27 = scores.slice(0, splitIdx);
    const meanTop = top27.length > 0 ? top27.reduce((a, b) => a + b, 0) / top27.length : 0;
    const meanBottom = bottom27.length > 0 ? bottom27.reduce((a, b) => a + b, 0) / bottom27.length : 0;
    const discrimination = (meanTop - meanBottom) / fullScore;

    stats.push({ 
      subject: sub, 
      participants: n, 
      max, 
      mean: parseFloat(mean.toFixed(2)), 
      stdDev: parseFloat(stdDev.toFixed(2)), 
      difficulty: parseFloat(difficulty.toFixed(2)), 
      discrimination: parseFloat(discrimination.toFixed(2)), 
      variance, 
      median,
      mode 
    });
  });
  const k = subjects.length, sumVarItems = stats.reduce((acc, s) => acc + s.variance, 0);
  const totalScores = periodData.map(s => s.currentTotal), meanTotal = totalScores.reduce((a, b) => a + b, 0) / n;
  const varTotal = totalScores.reduce((a, b) => a + Math.pow(b - meanTotal, 2), 0) / n;
  const reliability = k > 1 ? (k / (k - 1)) * (1 - (sumVarItems / varTotal)) : 1;
  return { subjectStats: stats, reliability: parseFloat(reliability.toFixed(2)) };
};

export const getStudentRadarData = (student: StudentRecord, selectedPeriod: string, subjects: string[], radarBaseline: 'class' | 'grade', periodData: any[]) => {
  const currentScores = student.history.find(h => h.period === selectedPeriod)?.scores || {};
  const baselineSource = radarBaseline === 'class' ? periodData.filter(s => s.class === student.class) : periodData;
  return subjects.map(sub => ({
    subject: sub,
    score: currentScores[sub] || 0,
    baseline: parseFloat((baselineSource.length > 0 ? baselineSource.reduce((acc, s) => acc + (s.currentScores?.[sub] || 0), 0) / baselineSource.length : 0).toFixed(1)),
    fullMark: 150
  }));
};

export const getStudentSubjectTrend = (student: StudentRecord, subject: string, allSubjectRanks: Record<string, Record<string, Record<string, number>>>) => {
  return student.history.map(h => ({ period: h.period, rank: allSubjectRanks[h.period]?.[subject]?.[student.name] || null })).filter(d => d.rank !== null);
};

export const getSubjectAverages = (periodData: any[], subjects: string[]) => {
  return subjects.map(sub => ({ name: sub, avg: parseFloat((periodData.reduce((acc, s) => acc + (s.currentScores[sub] || 0), 0) / periodData.length).toFixed(2)) }));
};

export const getClassSummaries = (periodData: any[], selectedClasses: string[]) => {
  return selectedClasses.map(cls => {
    const clsStudents = periodData.filter(s => s.class === cls);
    const totalAvg = clsStudents.length > 0 ? clsStudents.reduce((acc, s) => acc + s.currentTotal, 0) / clsStudents.length : 0;
    const top10Count = clsStudents.filter(s => s.periodSchoolRank <= 10).length;
    const top50Count = clsStudents.filter(s => s.periodSchoolRank <= 50).length;
    return { className: cls, count: clsStudents.length, average: parseFloat(totalAvg.toFixed(2)), top10: top10Count, top50: top50Count };
  });
};

export const getClassLeaderboard = (classSummaries: any[]) => {
  if (classSummaries.length === 0) return null;
  return {
    highestAvg: [...classSummaries].sort((a, b) => b.average - a.average)[0],
    mostTop10: [...classSummaries].sort((a, b) => b.top10 - a.top10)[0],
    mostTop50: [...classSummaries].sort((a, b) => b.top50 - a.top50)[0],
  };
};

export const calculateHeatmapMaxValues = (data: any[], selectedClasses: string[]) => {
  const map: Record<string, number> = {};
  data.forEach(row => { map[row.name] = Math.max(...selectedClasses.map(cls => row[cls] || 0)); });
  return map;
};
